function prm_robot_arm(startMode)

if nargin < 1, startMode = 3; end

if ischar(startMode) || (exist('isstring','builtin') && isstring(startMode))
    word = lower(strtrim(char(startMode)));
    switch word
        case {'kill','stop','close','end','quit'}
            prmKillAll(); return
        case {'1','2','3'}
            startMode = str2double(word);
        otherwise
            error(['Unknown option "%s". Use 1, 2, 3 or the word kill.'],word);
    end
end
if startMode == 3
    launchFBDMode();
    return
elseif startMode == 2
    launch3DMode();
    return
elseif startMode ~= 1
    error('startMode must be 1 (2D), 2 (3D), or 3 (FBD).');
end

p.linkR   = 0.05;
p.delta   = 0.10;
p.L       = 1.0;
p.groundZ = -0.10;
p.baseTop = 1 + 2*p.linkR;
p.twoPi   = 2*pi;
p.gridN   = 140;
p.kNeighbor = 10;
p.padPeriod = 0.02;
p.padDeadZone = 0.12;
p.padCutoffHz = 7;
p.padMaxVel = [1.2 1.2];
p.padMaxAccel = [5 5];
p.defaultQs = [0.25 0.25];
p.defaultQf = [3.84 4.86];
p.posLim  = [-1.6 1.6; -1.6 1.6; 0 2.4];
p.sizeLim = [0.05 1.2; 0.05 1.2; 0.05 1.2];
p.noiseDir = fullfile(fileparts(mfilename('fullpath')),'noise');

S.obs = [obsMake('sphere',[ 1.0 -0.6 0.40],[0.50 0.50 0.50],[0 0],obsPalette(1)), ...
         obsMake('box',   [-0.8  0.2 0.50],[0.70 0.70 0.90],[0 0],obsPalette(2))];
S.obsSel = 1;

S.pts     = zeros(0,2);
S.goodPts = zeros(0,2);
S.badPts  = zeros(0,2);
S.adj     = {};
S.edges   = zeros(0,4);

S.r     = 1.0;
S.rold  = -1;
S.qs = p.defaultQs;
S.qf = p.defaultQf;

S.progress = 0;
S.showObs  = false;
S.viewAng  = -pi/2;
S.workspaceView = [atan2d(cos(S.viewAng),-sin(S.viewAng)) atan2d(1,2)];
S.cameraDrag = false;
S.cameraLastPoint = [0 0];
S.armDrag = 0;
S.armPlanePoint = [0 0 0];
S.armPlaneNormal = [0 0 1];

S.path     = [];
S.pathType = -1;
S.totdist  = 0;
S.qsn = []; S.qfn = [];
S.diag = '';
S.traj = zeros(0,2);
S.frameClock = tic;

S.cfreeImg = [];
S.cfreeKey = [];
S.dragIdx  = 0;
S.sampleCursor = 1;
S.sampleSrc = 1;
S.sampleInfo = '';
S.padDrag = 0;
S.padTarget = zeros(2,2);
S.padFiltered = zeros(2,2);
S.padVelocity = zeros(2,2);
S.padLastTick = [];
S.padLastRender = [];
S.padLastPlan = [];
S.padWasMoving = false;

f = figure('Name','PRM Pro v12 - Robot Arm Motion Planner (2 joints)', ...
    'NumberTitle','off','Color',[0.08 0.09 0.11],'Position',[20 30 1440 860], ...
    'MenuBar','none','ToolBar','figure');

h.topPanel = uipanel('Parent',f,'Units','pixels','Position',[12 736 1416 112], ...
    'BackgroundColor',[0.13 0.14 0.16],'ForegroundColor',[0.55 0.58 0.64], ...
    'BorderType','line','HighlightColor',[0.30 0.32 0.36]);

mkLabel(h.topPanel,[20 84 130 17],'view angle');
h.sView = mkSlider(h.topPanel,[20 64 130 18],-pi/2,3*pi/2,S.viewAng,@viewChanged);
set(h.sView,'TooltipString','Change the 3D workspace camera angle.');
addlistener(h.sView,'ContinuousValueChange',@(~,~)viewChanged([],[]));

h.cbObs = uicontrol(h.topPanel,'Style','checkbox','String',' show C-obstacles', ...
    'Units','pixels','Position',[168 62 150 22], ...
    'BackgroundColor',[0.13 0.14 0.16],'ForegroundColor',[0.96 0.97 1.00], ...
    'Value',0,'Callback',@showObsChanged,'TooltipString', ...
    'Show or hide obstacle regions in configuration space.');

mkLabel(h.topPanel,[330 84 215 17],'vertex sampler');
h.samplerPopup = uicontrol(h.topPanel,'Style','popupmenu','Units','pixels', ...
    'Position',[330 60 215 24],'String',{'Halton - randomized', ...
    'Halton - fixed (repeatable)','rand - Mersenne Twister', ...
    'White-noise image (LSB)','random.org (API)'},'Value',1,'Callback',@samplerChanged);

mkLabel(h.topPanel,[560 84 175 17],'planner mode');
h.modePopup = uicontrol(h.topPanel,'Style','popupmenu','Units','pixels', ...
    'Position',[560 60 175 25],'String',{'2D - 2 joints','3D - 3 joints', ...
    'FBD robot'},'Value',1,'Callback',@switchMode);
centerPopupText(h.samplerPopup,h.modePopup);

uicontrol(h.topPanel,'Style','pushbutton','String','add 100 vertices', ...
    'Units','pixels','Position',[20 18 135 30],'FontWeight','bold', ...
    'Callback',@addPoints,'TooltipString','Add 100 collision-checked samples to the PRM roadmap.');
uicontrol(h.topPanel,'Style','pushbutton','String','restart map', ...
    'Units','pixels','Position',[163 18 95 30],'Callback',@restartAll, ...
    'TooltipString','Clear the roadmap and start a new sampling sequence.');
uicontrol(h.topPanel,'Style','pushbutton','String','reset arms', ...
    'Units','pixels','Position',[266 18 95 30],'FontWeight','bold', ...
    'Callback',@resetArms,'TooltipString','Restore the default START and GOAL arm poses.');

mkLabel(h.topPanel,[380 50 150 17],'progress');
h.sProg = mkSlider(h.topPanel,[380 28 150 18],0,1,0,@progChanged);
set(h.sProg,'TooltipString','Drag to inspect the robot along the current path.');
addlistener(h.sProg,'ContinuousValueChange',@(~,~)progChanged([],[]));

mkLabel(h.topPanel,[550 50 200 17],'radius');
h.sR = mkSlider(h.topPanel,[550 28 200 18],0,2,S.r,@radiusChanged);
set(h.sR,'TooltipString','Adjust the PRM connection radius.');
h.txtR = mkLabel(h.topPanel,[756 28 50 16],sprintf('%.2f',S.r));

uicontrol(h.topPanel,'Style','text','Units','pixels','Position',[830 8 570 92], ...
    'BackgroundColor',[0.13 0.14 0.16],'ForegroundColor',[0.60 0.64 0.71], ...
    'HorizontalAlignment','left','FontSize',9, ...
    'String',{'workspace: drag to orbit, scroll to zoom, double-click to reset'; ...
              'drag the green / red end-effector marker to move START / GOAL'; ...
              'phase space: drag the two round locators to place q_start / q_goal'; ...
              'obstacles below: pick a shape, then move it and change its size'});

h.obs = buildObsPanel(f,[12 620 940 108],@obsEdited,@obsSelected,@obsAdd,@obsRemove);
obsUIPushLimits(h.obs,p.posLim,p.sizeLim);
obsUIPush(h.obs,S.obs,S.obsSel);

h.txtInfo = uicontrol(f,'Style','text','Units','pixels', ...
    'Position',[962 620 466 104],'BackgroundColor',[0.13 0.14 0.16], ...
    'ForegroundColor',[0.92 0.94 0.98],'HorizontalAlignment','left', ...
    'FontSize',10,'FontWeight','bold','String','');

h.ax3 = axes('Parent',f,'Units','pixels','Position',[20 30 520 570]);
h.ax2 = axes('Parent',f,'Units','pixels','Position',[570 100 450 450]);

h.padPanel = uipanel('Parent',f,'Units','pixels','Position',[1045 30 385 570], ...
    'BackgroundColor',[0.13 0.14 0.16],'ForegroundColor',[0.55 0.58 0.64], ...
    'BorderType','line','HighlightColor',[0.30 0.32 0.36]);
h.startTitle = uicontrol(h.padPanel,'Style','text','Units','pixels', ...
    'Position',[15 516 355 26],'BackgroundColor',[0.13 0.14 0.16], ...
    'ForegroundColor',[0.20 0.82 0.48],'FontSize',13,'FontWeight','bold', ...
    'HorizontalAlignment','center','String','START configuration');
h.axPadStart = axes('Parent',h.padPanel,'Units','pixels','Position',[100 322 185 185]);
h.padStartKnob = makeCircularPad(h.axPadStart,[0.10 0.68 0.38]);
h.txtStartQ = uicontrol(h.padPanel,'Style','text','Units','pixels', ...
    'Position',[10 296 365 22],'BackgroundColor',[0.13 0.14 0.16], ...
    'ForegroundColor',[0.88 0.92 0.96],'FontSize',10,'FontWeight','bold', ...
    'HorizontalAlignment','center','String','');

h.goalTitle = uicontrol(h.padPanel,'Style','text','Units','pixels', ...
    'Position',[15 262 355 26],'BackgroundColor',[0.13 0.14 0.16], ...
    'ForegroundColor',[0.96 0.34 0.39],'FontSize',13,'FontWeight','bold', ...
    'HorizontalAlignment','center','String','GOAL configuration');
h.axPadGoal = axes('Parent',h.padPanel,'Units','pixels','Position',[100 68 185 185]);
h.padGoalKnob = makeCircularPad(h.axPadGoal,[0.88 0.23 0.30]);
h.txtGoalQ = uicontrol(h.padPanel,'Style','text','Units','pixels', ...
    'Position',[10 42 365 22],'BackgroundColor',[0.13 0.14 0.16], ...
    'ForegroundColor',[0.88 0.92 0.96],'FontSize',10,'FontWeight','bold', ...
    'HorizontalAlignment','center','String','');
uicontrol(h.padPanel,'Style','text','Units','pixels','Position',[15 14 355 20], ...
    'BackgroundColor',[0.13 0.14 0.16],'ForegroundColor',[0.62 0.66 0.72], ...
    'HorizontalAlignment','center','FontSize',9, ...
    'String','horizontal: theta_1     vertical: theta_2');

hideAxesChrome(h.axPadStart);
hideAxesChrome(h.axPadGoal);
disableAxesInteractions([h.ax3 h.ax2 h.axPadStart h.axPadGoal]);

title(h.ax3,'robot workspace','FontSize',13);
title(h.ax2,'robot phase space','FontSize',13);

set(f,'WindowButtonDownFcn',  @onDown, ...
      'WindowButtonMotionFcn',@onMove, ...
      'WindowButtonUpFcn',    @onUp, ...
      'WindowScrollWheelFcn', @workspaceWheel, ...
      'CloseRequestFcn',      @closeApp);

reclassify();
recomputePath();
redrawAll();

S.padLastTick = tic;
S.padLastRender = tic;
S.padLastPlan = tic;
S.padTimer = timer('ExecutionMode','fixedSpacing','Period',p.padPeriod, ...
    'BusyMode','drop','TimerFcn',@padTick,'Tag','PRM_TIMER');
start(S.padTimer);

    function obsEdited(~,~)
        if isempty(S.obs), return; end
        [oNew,typeChanged] = obsUIPull(h.obs,S.obs(S.obsSel));
        S.obs(S.obsSel) = oNew;
        if typeChanged
            obsUIPush(h.obs,S.obs,S.obsSel);
        else
            obsUIRefreshText(h.obs,S.obs(S.obsSel));
        end
        obstaclesChanged();
    end

    function obsSelected(~,~)
        if isempty(S.obs), return; end
        S.obsSel = get(h.obs.list,'Value');
        obsUIPush(h.obs,S.obs,S.obsSel);
    end

    function obsAdd(~,~)
        n = numel(S.obs) + 1;
        newType = obsUIAddType(h.obs);
        newC = obsSuggestedCenter(S.obs,S.obsSel,[0.0 1.0 0.6],p.posLim,n);
        S.obs(n) = obsMake(newType,newC, ...
            obsDefaultDim(newType,[0.40 0.40 0.40]),[0 0],obsPalette(n));
        S.obsSel = n;
        obsUIPush(h.obs,S.obs,S.obsSel);
        obstaclesChanged();
    end

    function obsRemove(~,~)
        if isempty(S.obs), return; end
        S.obs(S.obsSel) = [];
        if isempty(S.obs), S.obsSel=0; else, S.obsSel=min(S.obsSel,numel(S.obs)); end
        obsUIPush(h.obs,S.obs,S.obsSel);
        obstaclesChanged();
    end

    function obstaclesChanged()

        S.cfreeKey = [];
        reclassify();
        S.rold = -1;
        rebuildEdges();
        recomputePath();
        redrawAll();
    end

    function viewChanged(~,~)
        S.viewAng = get(h.sView,'Value');
        S.workspaceView(1) = atan2d(cos(S.viewAng),-sin(S.viewAng));
        applyView();
    end

    function showObsChanged(~,~)
        S.showObs = logical(get(h.cbObs,'Value'));
        redrawAll();
    end

    function radiusChanged(~,~)
        S.r = get(h.sR,'Value');
        set(h.txtR,'String',sprintf('%.2f',S.r));
        rebuildEdges();
        recomputePath();
        redrawAll();
    end

    function progChanged(~,~)
        S.progress = get(h.sProg,'Value');
        refreshProgress2();
    end

    function refreshProgress2()
        if ~isfield(h,'curTube2') || any(~isgraphics(h.curTube2))
            redrawAll(); return
        end
        if toc(S.frameClock) < 0.016, return; end
        S.frameClock = tic;
        updateCurrentRobot2();
        drawnow limitrate nocallbacks
    end

    function updateCurrentRobot2()
        q = robotQ(); a1 = q(1); a2 = q(2);
        P1 = [0 0 1];
        P2 = [cos(a1) sin(a1) 1];
        P3 = P2 + [sin(a1)*sin(a2), -cos(a1)*sin(a2), cos(a2)];
        setTubeData(h.curTube2(1),P1,P2,p.linkR);
        setTubeData(h.curTube2(2),P2,P3,p.linkR);
        setSphData(h.curSph2(1),P1,0.075);
        setSphData(h.curSph2(2),P2,0.075);
        setSphData(h.curSph2(3),P3,0.060);
        if isfield(h,'curDot2') && isgraphics(h.curDot2)
            set(h.curDot2,'XData',q(1),'YData',q(2));
        end
    end

    function addPoints(~,~)
        setBusy(true);
        startIdx = size(S.goodPts,1) + 1;
        srcs = {'halton','halton_fixed','rand','image','api'};
        [U,S.sampleInfo] = prmSample(100,2,srcs{S.sampleSrc}, ...
            p.noiseDir,S.sampleCursor);
        newpts = U*p.twoPi;
        S.sampleCursor = S.sampleCursor + 100;
        S.pts    = [S.pts; newpts];
        c        = collideMany(newpts);
        S.goodPts = [S.goodPts; newpts(~c,:)];
        S.badPts  = [S.badPts;  newpts( c,:)];
        S.adj(end+1:size(S.goodPts,1)) = {[]};
        if S.r > 0
            connectPoints(startIdx);
        end
        S.rold = S.r;
        recomputePath();
        redrawAll();
        setBusy(false);
    end

    function samplerChanged(~,~)
        S.sampleSrc = get(h.samplerPopup,'Value');
        S.sampleInfo = '';
    end

    function restartAll(~,~)
        S.pts = zeros(0,2); S.goodPts = zeros(0,2); S.badPts = zeros(0,2);
        S.adj = {}; S.edges = zeros(0,4); S.rold = -1; S.sampleCursor = 1;
        recomputePath(); redrawAll();
    end

    function resetArms(~,~)
        S.qs=p.defaultQs; S.qf=p.defaultQf; S.progress=0;
        S.padTarget(:)=0; S.padFiltered(:)=0; S.padVelocity(:)=0;
        S.padWasMoving=false; S.padDrag=0; S.armDrag=0; S.dragIdx=0;
        S.cameraDrag=false;
        updatePadKnob(1,[0 0]); updatePadKnob(2,[0 0]);
        set(h.sProg,'Value',0);
        if isgraphics(f), set(f,'Pointer','arrow'); end
        recomputePath(); redrawAll();
        S.padLastPlan=tic; S.padLastRender=tic;
    end

    function onDown(~,~)
        [padId,xy] = padHit();
        if padId > 0
            S.padDrag = padId;
            S.padTarget(padId,:) = xy;
            updatePadKnob(padId,xy);
            return
        end

        obj = currentHitObject2D(); tag = '';
        if ~isempty(obj) && isgraphics(obj)
            try, tag = get(obj,'Tag'); catch, tag = ''; end
        end
        primaryClick = strcmp(get(f,'SelectionType'),'normal');
        if primaryClick && strcmp(tag,'PRM2_START_TIP')
            beginArmDrag2D(1); return
        elseif primaryClick && strcmp(tag,'PRM2_GOAL_TIP')
            beginArmDrag2D(2); return
        end

        hitAx = currentHitAxes2D();
        if isempty(hitAx) && primaryClick
            armHit = pickArmNearCursor2D();
            if armHit > 0, beginArmDrag2D(armHit); return; end
        end
        if isequal(hitAx,h.ax3)
            if primaryClick
                armHit = pickArmNearCursor2D();
                if armHit > 0, beginArmDrag2D(armHit); return; end
            end
            if strcmp(get(f,'SelectionType'),'open')
                resetWorkspaceCamera();
            else
                S.cameraDrag = true;
                S.cameraLastPoint = get(f,'CurrentPoint');
                set(f,'Pointer','fleur');
            end
            return
        end
        if ~isequal(hitAx,h.ax2), return; end

        q = axPoint();
        if isempty(q), return; end
        d = [toroidDist(q,S.qs) toroidDist(q,S.qf)];
        [dm,k] = min(d);
        if dm < 0.45
            S.dragIdx = k;
            moveLocator(q);
        end
    end

    function onMove(~,~)
        if S.padDrag > 0
            xy = padPoint(S.padDrag);
            if ~isempty(xy)
                S.padTarget(S.padDrag,:) = xy;
                updatePadKnob(S.padDrag,xy);
            end
            return
        end
        if S.armDrag > 0
            target = cursorPlaneTarget2D();
            if ~isempty(target)
                if S.armDrag == 1
                    S.qs = solveIK2D(S.qs,target);
                else
                    S.qf = solveIK2D(S.qf,target);
                end
                if toc(S.padLastPlan) >= 0.12
                    recomputePath(); S.padLastPlan = tic;
                end
                if toc(S.padLastRender) >= 0.07
                    redrawAll(); S.padLastRender = tic;
                end
            end
            return
        end
        if S.cameraDrag
            pt = get(f,'CurrentPoint');
            dp = pt-S.cameraLastPoint;
            S.cameraLastPoint = pt;
            S.workspaceView = orbitView(S.workspaceView,dp);
            syncViewSlider2();
            view(h.ax3,S.workspaceView);
            drawnow limitrate nocallbacks
            return
        end
        if S.dragIdx == 0, return; end
        q = axPoint();
        if isempty(q), return; end
        moveLocator(q);
    end

    function onUp(~,~)
        armWasDragging = S.armDrag > 0;
        if S.padDrag > 0
            releasedPad = S.padDrag;
            S.padTarget(releasedPad,:) = [0 0];
            updatePadKnob(releasedPad,[0 0]);
            S.padDrag = 0;
        end
        S.armDrag = 0;
        S.dragIdx = 0;
        S.cameraDrag = false;
        if isgraphics(f), set(f,'Pointer','arrow'); end
        if armWasDragging
            recomputePath(); redrawAll();
            S.padLastPlan = tic; S.padLastRender = tic;
        end
    end

    function obj = currentHitObject2D()
        try, obj = hittest(f); catch, obj = get(f,'CurrentObject'); end
    end

    function ax = currentHitAxes2D()
        ax = axesAtPointer(f,[h.ax3 h.ax2],24);
    end

    function beginArmDrag2D(whichArm)
        S.armDrag = whichArm; S.cameraDrag = false;
        S.padTarget(:)=0; S.padFiltered(:)=0; S.padVelocity(:)=0;
        S.padWasMoving=false;
        if whichArm == 1, q = S.qs; else, q = S.qf; end
        tip = robotTip2D(q);
        n = campos(h.ax3)-camtarget(h.ax3);
        if norm(n) < 1e-12, n = [0 0 1]; else, n = n/norm(n); end
        S.armPlanePoint = tip; S.armPlaneNormal = n;
        set(f,'Pointer','crosshair');
    end

    function whichArm = pickArmNearCursor2D()
        whichArm = 0;
        cp = get(h.ax3,'CurrentPoint'); r0 = cp(1,:); ray = cp(2,:)-cp(1,:);
        rayNorm = norm(ray);
        if rayNorm < 1e-12, return; end
        tips = [robotTip2D(S.qs); robotTip2D(S.qf)];
        rayCross = cross(tips-r0,repmat(ray,2,1),2);
        d = sqrt(sum(rayCross.^2,2))/rayNorm;
        tol = armPickTolerance(h.ax3);
        [dm,k] = min(d);
        if dm <= tol, whichArm = k; end
    end

    function target = cursorPlaneTarget2D()
        cp = get(h.ax3,'CurrentPoint'); r0 = cp(1,:); ray = cp(2,:)-cp(1,:);
        den = dot(ray,S.armPlaneNormal);
        if abs(den) < 1e-10, target = []; return; end
        target = r0 + (dot(S.armPlanePoint-r0,S.armPlaneNormal)/den)*ray;
        target = max(min(target,[2.15 2.15 2.45]), ...
            [-2.15 -2.15 p.groundZ+p.linkR]);
    end

    function tip = robotTip2D(q)
        a1 = q(1); a2 = q(2);
        p2 = [cos(a1) sin(a1) 1];
        tip = p2 + [sin(a1)*sin(a2),-cos(a1)*sin(a2),cos(a2)];
    end

    function q = solveIK2D(q,target)
        epsJ = 1e-4; lambda = 0.06;
        for iter = 1:20
            tip = robotTip2D(q); err = target-tip; oldNorm = norm(err);
            if oldNorm < 2e-3, break; end
            J = zeros(3,2);
            for k = 1:2
                qd = q; qd(k) = mod(qd(k)+epsJ,p.twoPi);
                J(:,k) = ((robotTip2D(qd)-tip)/epsJ)';
            end
            dq = J'*((J*J'+lambda^2*eye(3))\err');
            if norm(dq) > 0.20, dq = dq*(0.20/norm(dq)); end
            improved = false; scale = 1;
            for ls = 1:5
                candidate = mod(q+(scale*dq)',p.twoPi);
                if norm(target-robotTip2D(candidate)) < oldNorm
                    q = candidate; improved = true; break
                end
                scale = scale/2;
            end
            if ~improved, break; end
        end
    end

    function workspaceWheel(~,evt)
        if ~isequal(currentHitAxes2D(),h.ax3), return; end
        mods = get(f,'CurrentModifier');
        steps = evt.VerticalScrollCount;
        if any(strcmp(mods,'shift'))
            S.workspaceView = orbitView(S.workspaceView,[6*steps 0]);
            syncViewSlider2(); view(h.ax3,S.workspaceView);
        elseif any(strcmp(mods,'alt')) || any(strcmp(mods,'control'))
            S.workspaceView = orbitView(S.workspaceView,[0 6*steps]);
            view(h.ax3,S.workspaceView);
        else
            boundedCamzoom(h.ax3,1.12^(-steps));
        end
        drawnow limitrate nocallbacks
    end

    function syncViewSlider2()
        vdeg = mod(S.workspaceView(1),360) - 90;
        S.viewAng = vdeg*pi/180;
        lo = get(h.sView,'Min'); hi = get(h.sView,'Max');
        set(h.sView,'Value',min(max(S.viewAng,lo),hi));
    end

    function resetWorkspaceCamera()
        S.viewAng = -pi/2;
        S.workspaceView = [atan2d(cos(S.viewAng),-sin(S.viewAng)) atan2d(1,2)];
        set(h.sView,'Value',S.viewAng);
        view(h.ax3,S.workspaceView);
        camva(h.ax3,'auto');
        drawnow limitrate nocallbacks
    end

    function [padId,xy] = padHit()
        padId = 0; xy = [];
        ax = axesAtPointer(f,[h.axPadStart h.axPadGoal]);
        if isequal(ax,h.axPadStart)
            padId = 1;
        elseif isequal(ax,h.axPadGoal)
            padId = 2;
        end
        if padId > 0
            xy = padPoint(padId);
            if isempty(xy), padId = 0; end
        end
    end

    function xy = padPoint(padId)
        if padId == 1, ax = h.axPadStart; else, ax = h.axPadGoal; end
        cp = get(ax,'CurrentPoint');
        xy = cp(1,1:2);
        if any(~isfinite(xy)) || norm(xy) > 1.25
            xy = [];
            return
        end
        r = norm(xy);
        if r > 1, xy = xy/r; end
    end

    function updatePadKnob(padId,xy)
        if padId == 1, knob = h.padStartKnob; else, knob = h.padGoalKnob; end
        if isgraphics(knob), set(knob,'XData',xy(1),'YData',xy(2)); end
    end

    function padTick(~,~)
        if ~isgraphics(f), return; end
        dt = min(max(toc(S.padLastTick),0.001),0.06);
        S.padLastTick = tic;
        changed = false;
        alpha = 1-exp(-2*pi*p.padCutoffHz*dt);
        for padId = 1:2
            xy = S.padTarget(padId,:);
            r = norm(xy);
            if r <= p.padDeadZone
                shaped = [0 0];
            else
                shaped = (xy/r)*((r-p.padDeadZone)/(1-p.padDeadZone));
            end
            S.padFiltered(padId,:) = S.padFiltered(padId,:) + ...
                alpha*(shaped-S.padFiltered(padId,:));
            desired = S.padFiltered(padId,:).*p.padMaxVel;
            maxStep = p.padMaxAccel*dt;
            dv = min(max(desired-S.padVelocity(padId,:),-maxStep),maxStep);
            S.padVelocity(padId,:) = S.padVelocity(padId,:) + dv;
            if norm(S.padVelocity(padId,:)) > 1e-4
                if padId == 1
                    S.qs = mod(S.qs + S.padVelocity(padId,:)*dt,p.twoPi);
                else
                    S.qf = mod(S.qf + S.padVelocity(padId,:)*dt,p.twoPi);
                end
                changed = true;
            end
        end
        if changed
            S.padWasMoving = true;
            if toc(S.padLastPlan) >= 0.10
                recomputePath();
                S.padLastPlan = tic;
            end
            if toc(S.padLastRender) >= 0.060
                redrawAll();
                S.padLastRender = tic;
            end
        elseif S.padWasMoving
            recomputePath();
            redrawAll();
            S.padLastPlan = tic;
            S.padLastRender = tic;
            S.padWasMoving = false;
        end
    end

    function switchMode(~,~)
        v = get(h.modePopup,'Value');
        if v == 1, return; end
        obsCopy = S.obs;
        closeApp([],[]);
        drawnow;
        if v == 2
            launch3DMode(obsCopy);
        else
            launchFBDMode();
        end
    end

    function closeApp(~,~)
        try
            if isfield(S,'padTimer') && isvalid(S.padTimer)
                stop(S.padTimer);
                delete(S.padTimer);
            end
        catch
        end
        if isgraphics(f), delete(f); end
    end

    function moveLocator(q)
        q = mod(q, p.twoPi);
        if S.dragIdx == 1, S.qs = q; else, S.qf = q; end
        recomputePath();
        redrawAll();
    end

    function q = axPoint()
        q = [];
        cp = get(h.ax2,'CurrentPoint');
        x = cp(1,1); y = cp(1,2);
        if x < -0.3 || x > p.twoPi+0.3 || y < -0.3 || y > p.twoPi+0.3
            return
        end
        q = [x y];
    end

    function reclassify()
        if isempty(S.pts)
            S.goodPts = zeros(0,2); S.badPts = zeros(0,2); S.adj = {};
            S.edges = zeros(0,4);
            return
        end
        c = collideMany(S.pts);
        S.goodPts = S.pts(~c,:);
        S.badPts  = S.pts( c,:);
        S.adj     = repmat({[]}, 1, size(S.goodPts,1));
        S.edges   = zeros(0,4);
    end

    function rebuildEdges()
        n = size(S.goodPts,1);
        S.adj   = repmat({[]}, 1, n);
        S.edges = zeros(0,4);
        if S.r > 0 && n > 1
            setBusy(true);
            connectPoints(1);
            setBusy(false);
        end
        S.rold = S.r;
    end

    function connectPoints(startIdx)
        G = S.goodPts;  n = size(G,1);
        eBuf = zeros(0,4);
        for i = max(1,startIdx):n
            d = toroidDistMany(G,G(i,:));
            d(i) = inf;
            [ds,order] = sort(d,'ascend');
            order = order(ds <= S.r);
            order = order(1:min(p.kNeighbor,numel(order)));
            for j = order(:)'
                if any(S.adj{i} == j), continue; end
                if pathOKT(G(i,:), G(j,:))
                    S.adj{i}(end+1) = j;
                    S.adj{j}(end+1) = i;
                    eBuf(end+1,:) = [G(i,:) G(j,:)];
                end
            end
        end
        S.edges = [S.edges; eBuf];
    end

    function recomputePath()
        S.path = []; S.pathType = -1; S.totdist = 0;
        S.qsn = []; S.qfn = []; S.traj = zeros(0,2);

        if collideMany(S.qs) || collideMany(S.qf), return; end

        if toroidDist(S.qs,S.qf) < S.r && pathOKT(S.qs,S.qf)
            S.traj = [S.qs; S.qf];
            S.pathType = -2;
            S.totdist = toroidDist(S.qs,S.qf);
            return
        end

        G = S.goodPts;
        if size(G,1) <= 5, return; end
        si = connectToRoadmap(S.qs);
        gi = connectToRoadmap(S.qf);
        if ~isempty(si), S.qsn = si(1); end
        if ~isempty(gi), S.qfn = gi(1); end
        if isempty(si) || isempty(gi), return; end

        pth = astarSearchMulti(si,gi);
        if isempty(pth), return; end

        fullp = [S.qs; G(pth,:); S.qf];
        for k = 1:size(fullp,1)-1
            if ~pathOKT(fullp(k,:),fullp(k+1,:)), return; end
        end
        S.path = pth;
        S.pathType = 1;
        S.qsn = pth(1);
        S.qfn = pth(end);
        S.traj = fullp;
        S.totdist = sum(toroidDist(fullp(1:end-1,:),fullp(2:end,:)));
    end

    function ids = connectToRoadmap(q)
        ids = [];
        G = S.goodPts;
        d = toroidDistMany(G,q);
        [~,order] = sort(d,'ascend');
        if ~isempty(order) && pathOKT(q,G(order(1),:))
            ids = order(1);
        end
    end

    function pth = astarSearchMulti(startNodes,goalNodes)
        G = S.goodPts;
        n = size(G,1);
        s = n + 1; t = n + 2;
        A = [S.adj(:); {startNodes(:)'}; {goalNodes(:)'}];
        for id = startNodes(:)'
            A{id}(end+1) = s;
        end
        for id = goalNodes(:)'
            A{id}(end+1) = t;
        end
        ids = astarGeneric(A,[G;S.qs;S.qf],s,t,@toroidDist);
        pth = ids(ids <= n);
    end

    function ok = pathOKT(q1, q2)
        d = toroidDist(q1,q2);
        if d <= p.delta, ok = true; return; end
        n  = ceil(d/p.delta);
        t  = (1:n)'/(n+1);
        dq = wrapPi(q2 - q1);
        Q  = mod(q1 + t*dq, p.twoPi);
        ok = ~any(collideMany(Q));
    end

    function c = collideMany(Q)
        c = false(size(Q,1),1);
        for i = 1:numel(S.obs)
            c = c | linksCollide(Q(:,1),Q(:,2),S.obs(i));
        end
    end

    function c = linksCollide(A1, A2, o)
        N  = numel(A1);
        A1 = A1(:); A2 = A2(:);
        P0 = repmat([0 0 1], N, 1);
        P1 = [cos(A1), sin(A1), ones(N,1)];
        D2 = [sin(A1).*sin(A2), -cos(A1).*sin(A2), cos(A2)];
        P2 = P1 + D2;
        B0 = repmat([0 0 p.groundZ], N, 1);
        B1 = repmat([0 0 p.baseTop], N, 1);
        c = obsSegDist(P0,P1,o) < p.linkR | ...
            obsSegDist(P1,P2,o) < p.linkR | ...
            obsSegDist(B0,B1,o) < 2*p.linkR;
    end

    function redrawAll()
        if S.pathType == -1
            S.progress = 0;
            set(h.sProg,'Value',0,'Enable','off', ...
                'TooltipString','Progress is available after a collision-free path is found.');
        else
            set(h.sProg,'Enable','on', ...
                'TooltipString','Drag to move the robot along the collision-free path.');
        end
        drawWorkspace();
        drawPhaseSpace();
        set(h.txtStartQ,'String',sprintf('START  theta_1 = %.2f   theta_2 = %.2f',S.qs));
        set(h.txtGoalQ,'String', sprintf('GOAL   theta_1 = %.2f   theta_2 = %.2f',S.qf));
        startBad = collideMany(S.qs); goalBad = collideMany(S.qf);
        if S.pathType == -1
            if startBad, reason = 'START in collision';
            elseif goalBad, reason = 'GOAL in collision';
            elseif isempty(S.qsn) && isempty(S.qfn), reason = 'add vertices / increase radius';
            else, reason = 'roadmap components disconnected'; end
            msg = {sprintf('Progress locked: %s',reason); ...
                   sprintf('V = %d free / %d blocked',size(S.goodPts,1),size(S.badPts,1)); ...
                   sprintf('obstacles: %d',numel(S.obs))};
        else
            msg = {sprintf('Path length = %.3f rad',S.totdist); ...
                   sprintf('V = %d,  E = %d',size(S.goodPts,1),size(S.edges,1)); ...
                   sprintf('obstacles: %d   %s',numel(S.obs),S.sampleInfo)};
        end
        set(h.txtInfo,'String',msg);
        drawnow limitrate nocallbacks
    end

    function drawWorkspace()
        ax = h.ax3;
        cla(ax); hold(ax,'on');

        inCs = collideMany(S.qs);
        inCf = collideMany(S.qf);

        drawGroundPlane(ax,[-2.2 2.2],[-2.2 2.2],p.groundZ,[0.90 0.92 0.95],0.72);
        drawWireBox(ax,[-2.2 2.2],[-2.2 2.2],[p.groundZ 2.5],[0.70 0.74 0.81],0.65);

        drawRobot(ax, S.qs, [0.55 0.35 0.20], 0.20);
        drawRobot(ax, S.qf, [0.55 0.35 0.20], 0.20);

        if inCs, baseCol = [0.85 0.15 0.15]; else, baseCol = [0.45 0.28 0.15]; end
        drawTube(ax,[0 0 p.groundZ],[0 0 p.baseTop],1/8,baseCol,1);
        drawSphere(ax,[0 0 1],0.10,baseCol,1);

        h.curTube2 = gobjects(1,2); h.curSph2 = gobjects(1,3);
        for kk = 1:2, h.curTube2(kk) = newTube(ax,[0.45 0.28 0.15],1); end
        for kk = 1:3, h.curSph2(kk)  = newSph(ax,[0.45 0.28 0.15],1); end
        updateCurrentRobot2();

        for i = 1:numel(S.obs)
            drawObstacle(ax,S.obs(i),1);
        end

        tipS = robotTip2D(S.qs); tipG = robotTip2D(S.qf);
        h.startTip2=scatter3(ax,tipS(1),tipS(2),tipS(3),95,'o','filled', ...
            'MarkerFaceColor',[0.10 0.82 0.42],'MarkerEdgeColor','w', ...
            'LineWidth',1.4,'Tag','PRM2_START_TIP','PickableParts','all');
        h.goalTip2=scatter3(ax,tipG(1),tipG(2),tipG(3),95,'o','filled', ...
            'MarkerFaceColor',[0.96 0.25 0.32],'MarkerEdgeColor','w', ...
            'LineWidth',1.4,'Tag','PRM2_GOAL_TIP','PickableParts','all');

        daspect(ax,[1 1 1]);
        set(ax,'XLim',[-2.2 2.2],'YLim',[-2.2 2.2],'ZLim',[p.groundZ 2.5], ...
               'XTick',[],'YTick',[],'ZTick',[],'Box','off', ...
               'Color',[1 1 1],'XColor','none','YColor','none','ZColor','none', ...
               'SortMethod','depth');
        trySet(ax,'ClippingStyle','rectangle');
        title(ax,'robot workspace','FontSize',13,'Color','k');
        light('Parent',ax,'Style','infinite','Position',[1 -1 2]);
        light('Parent',ax,'Style','infinite','Position',[-1 1 1]);
        lighting(ax,'gouraud');
        applyView();
        hold(ax,'off');

        if inCf, set(get(ax,'Title'),'String','robot workspace  (goal in collision)');
        elseif inCs, set(get(ax,'Title'),'String','robot workspace  (start in collision)');
        end
    end

    function applyView()
        view(h.ax3,S.workspaceView);
    end

    function q = robotQ()
        q = S.qs;
        if S.pathType == -1 || ~isfield(S,'traj') || size(S.traj,1) < 2, return; end
        Q = S.traj;
        dists = toroidDist(Q(1:end-1,:),Q(2:end,:));
        tot = sum(dists);
        if tot < 1e-9, return; end
        target = S.progress*tot; acc = 0; c = 1;
        while c < numel(dists) && acc + dists(c) < target
            acc = acc + dists(c); c = c + 1;
        end
        q = toroidPt(Q(c,:), Q(c+1,:), (target-acc)/max(dists(c),1e-9));
    end

    function drawRobot(ax, q, col, alpha)
        a1 = q(1); a2 = q(2);
        P1 = [0 0 1];
        P2 = [cos(a1) sin(a1) 1];
        P3 = P2 + [sin(a1)*sin(a2), -cos(a1)*sin(a2), cos(a2)];
        drawTube(ax,P1,P2,p.linkR,col,alpha);
        drawTube(ax,P2,P3,p.linkR,col,alpha);
        drawSphere(ax,P1,0.075,col,alpha);
        drawSphere(ax,P2,0.075,col,alpha);
        drawSphere(ax,P3,0.060,col,alpha);
    end

    function drawPhaseSpace()
        ax = h.ax2;
        cla(ax); hold(ax,'on');

        if S.showObs
            img = cfreeImage();
            image('Parent',ax,'XData',[0 p.twoPi],'YData',[0 p.twoPi],'CData',img);
        end

        if ~isempty(S.edges)
            Q1 = S.edges(:,1:2);
            Q2 = Q1 + wrapPi(S.edges(:,3:4) - Q1);
            drawToroidSegs(ax,Q1,Q2,[0.72 0.55 0.40],0.5);
        end

        if S.pathType ~= -1 && isfield(S,'traj') && size(S.traj,1) > 1
            A = S.traj(1:end-1,:); B = A + wrapPi(S.traj(2:end,:) - A);
            drawToroidSegs(ax,A,B,[1 0 1],2.8);
        end

        if ~isempty(S.badPts)
            plot(ax,S.badPts(:,1),S.badPts(:,2),'.','Color',[0.9 0.1 0.1],'MarkerSize',9);
        end
        if ~isempty(S.goodPts)
            plot(ax,S.goodPts(:,1),S.goodPts(:,2),'.','Color',[0 0.5 0],'MarkerSize',11);
        end

        rq = robotQ();
        h.curDot2 = plot(ax,rq(1),rq(2),'o','MarkerSize',7, ...
             'MarkerFaceColor',[0.20 0.45 1],'MarkerEdgeColor','none','Tag','PRM2_CURC');

        drawLocator(ax,S.qs,collideMany(S.qs),[0.10 0.78 0.35]);
        drawLocator(ax,S.qf,collideMany(S.qf),[0.95 0.25 0.30]);

        axis(ax,'square');
        set(ax,'XLim',[0 p.twoPi],'YLim',[0 p.twoPi],'YDir','normal', ...
               'XTick',0:pi/2:p.twoPi,'YTick',0:pi/2:p.twoPi, ...
               'XTickLabel',{'0','\pi/2','\pi','3\pi/2','2\pi'}, ...
               'YTickLabel',{'0','\pi/2','\pi','3\pi/2','2\pi'}, ...
               'Box','on','Layer','top');
        xlabel(ax,'\theta_1','FontSize',13);
        ylabel(ax,'\theta_2','FontSize',13);
        title(ax,'robot phase space','FontSize',13);
        hold(ax,'off');
    end

    function drawLocator(ax,q,bad,col)
        if nargin < 4 || isempty(col), col = [0 0.55 0]; end
        if bad
            plot(ax,q(1),q(2),'o','MarkerSize',20,'LineWidth',2.5,'Color',[0.95 0.15 0.15]);
        end
        plot(ax,q(1),q(2),'o','MarkerSize',13,'LineWidth',2,'Color',col);
        plot(ax,q(1),q(2),'+','MarkerSize',16,'LineWidth',1.5,'Color',col);
    end

    function img = cfreeImage()
        key = obsKey(S.obs);
        if ~isempty(S.cfreeKey) && isequal(key,S.cfreeKey)
            img = S.cfreeImg; return
        end
        setBusy(true);
        N  = p.gridN;
        lin = linspace(0,p.twoPi,N);
        [A1,A2] = meshgrid(lin,lin);
        img = ones(N,N,3);
        for i = 1:numel(S.obs)
            m = reshape(linksCollide(A1(:),A2(:),S.obs(i)),N,N);
            col = 0.35 + 0.65*S.obs(i).color;
            for k = 1:3
                L = img(:,:,k);
                L(m) = min(L(m),col(k));
                img(:,:,k) = L;
            end
        end
        S.cfreeImg = img; S.cfreeKey = key;
        setBusy(false);
    end

    function setBusy(on)
        if ~isgraphics(f), return; end
        if on, set(f,'Pointer','watch'); else, set(f,'Pointer','arrow'); end
        drawnow limitrate
    end
end

function launch3DMode(obsIn)

p.twoPi = 2*pi;
p.linkR = 0.05;
p.groundZ = -0.10;
p.baseTop = 1 + 2*p.linkR;
p.baseRadius = 0.13;
p.delta = 0.025;
p.kNeighbor = 14;
p.clearance = 0.06;
p.selfClearance = 0.03;
p.padPeriod = 0.02;
p.padDeadZone = 0.12;
p.padCutoffHz = 7;
p.padMaxVel = [1.0 1.0];
p.padMaxAccel = [4.0 4.0];
p.surfaceN = 22;
p.defaultQs = [0.25 0.25 0.25];
p.defaultQf = [3.84 4.86 1.62];
p.tTotal = 5.5;
p.animPeriod = 0.04;
p.posLim  = [-2.0 2.0; -2.0 2.0; 0 2.6];
p.sizeLim = [0.05 1.3; 0.05 1.3; 0.05 1.3];
p.noiseDir = fullfile(fileparts(mfilename('fullpath')),'noise');

p.wolframViewPoint = [1.3 -2.4 2.0];
p.defaultView = [atan2d(p.wolframViewPoint(2),p.wolframViewPoint(1)), ...
    atan2d(p.wolframViewPoint(3),hypot(p.wolframViewPoint(1),p.wolframViewPoint(2)))];

if nargin >= 1 && ~isempty(obsIn)
    S.obs = obsIn;
else
    S.obs = [obsMake('sphere',  [1.00  0.00 0.00],[0.50 0.50 0.50],[0 0],obsPalette(1)), ...
             obsMake('cylinder',[0.00 -1.00 0.50],[0.45 1.20 0.45],[0 0],obsPalette(2))];
end
S.obsSel = 1;

S.pts = zeros(0,3);
S.goodPts = zeros(0,3);
S.badPts = zeros(0,3);
S.adj = {};
S.edges = zeros(0,6);
S.r = 1.55;
S.qs = p.defaultQs;
S.qf = p.defaultQf;
S.path = [];
S.pathType = -1;
S.qsn = []; S.qfn = [];
S.diag = '';
S.traj = zeros(0,3);
S.rawTraj = zeros(0,3);
S.frameClock = tic;
S.totdist = 0;
S.progress = 0;
S.showCObs = false;
S.workspaceView = p.defaultView;
S.configView = p.defaultView;
S.viewAng = S.workspaceView(1)*pi/180;
S.cameraDrag = 0;
S.cameraLastPoint = [0 0];
S.lastCameraAxis = 1;
S.armDrag = 0;
S.armPlanePoint = [0 0 0];
S.armPlaneNormal = [0 0 1];
S.sampleCursor = 1;
S.sampleSrc = 1;
S.sampleInfo = '';
S.surfaceKey = [];
S.surfaces = {};
S.padDrag = 0;
S.padTarget = zeros(2,2);
S.padFiltered = zeros(2,2);
S.padVelocity = zeros(2,2);
S.padLastTick = [];
S.padLastRender = [];
S.padLastPlan = [];
S.padWasMoving = false;
S.animOn = false;
S.animDir = 1;
S.animClock = [];
S.animTimer = [];

f3 = figure('Name','PRM Pro v12 - 3D Configuration Space (3 joints)', ...
    'NumberTitle','off','Color',[0.08 0.09 0.11], ...
    'Position',[20 20 1440 880],'MenuBar','none','ToolBar','figure');

h.top = uipanel('Parent',f3,'Units','pixels','Position',[12 756 1416 112], ...
    'BackgroundColor',[0.13 0.14 0.16],'BorderType','line', ...
    'HighlightColor',[0.30 0.32 0.36]);

mkLabel(h.top,[20 84 130 17],'view angle');
h.view = mkSlider(h.top,[20 64 130 18],-pi/2,3*pi/2,S.viewAng,@viewChanged);
set(h.view,'TooltipString','Change the 3D workspace camera angle.');
addlistener(h.view,'ContinuousValueChange',@(~,~)viewChanged([],[]));

h.show = uicontrol(h.top,'Style','checkbox','String',' show C-space obstacles', ...
    'Units','pixels','Position',[168 62 190 22], ...
    'BackgroundColor',[0.13 0.14 0.16],'ForegroundColor',[0.96 0.97 1], ...
    'Value',0,'Callback',@showChanged,'TooltipString', ...
    'Show or hide obstacle regions in the 3D configuration space.');

mkLabel(h.top,[370 84 215 17],'vertex sampler');
h.sampler = uicontrol(h.top,'Style','popupmenu','Units','pixels', ...
    'Position',[370 60 215 24],'String',{'Halton - randomized', ...
    'Halton - fixed (repeatable)','rand - Mersenne Twister', ...
    'White-noise image (LSB)','random.org (API)'},'Value',1,'Callback',@samplerChanged3);

mkLabel(h.top,[600 84 175 17],'planner mode');
h.mode = uicontrol(h.top,'Style','popupmenu','Units','pixels', ...
    'Position',[600 60 175 25],'String',{'2D - 2 joints','3D - 3 joints', ...
    'FBD robot'},'Value',2,'Callback',@switchMode);
centerPopupText(h.sampler,h.mode);

h.cbSmooth = uicontrol(h.top,'Style','checkbox','String',' smooth path', ...
    'Units','pixels','Position',[790 62 125 22], ...
    'BackgroundColor',[0.13 0.14 0.16],'ForegroundColor',[0.96 0.97 1], ...
    'Value',0,'TooltipString',[ ...
    'OFF by default: follow every collision-certified PRM waypoint. ' ...
    'Turn ON to shortcut and round the path, with collision checks repeated.'], ...
    'Callback',@(~,~)smoothChanged3());

uicontrol(h.top,'Style','pushbutton','String','add 100 vertices', ...
    'Units','pixels','Position',[20 18 135 30],'FontWeight','bold', ...
    'Callback',@addPoints,'TooltipString','Add 100 collision-checked samples to the PRM roadmap.');
uicontrol(h.top,'Style','pushbutton','String','restart map', ...
    'Units','pixels','Position',[163 18 95 30],'Callback',@restartMap, ...
    'TooltipString','Clear the roadmap and start a new sampling sequence.');
uicontrol(h.top,'Style','pushbutton','String','reset arms', ...
    'Units','pixels','Position',[266 18 95 30],'FontWeight','bold', ...
    'Callback',@resetArms,'TooltipString','Restore the default START and GOAL arm poses.');
h.play = uicontrol(h.top,'Style','pushbutton','String','> play', ...
    'Units','pixels','Position',[369 18 70 30],'FontWeight','bold', ...
    'Callback',@togglePlay3,'TooltipString','Play or pause the robot along the current path.');

mkLabel(h.top,[455 42 150 17],'progress');
