    function makePanelTitle(parent,pos,label,col)
        uicontrol(parent,'Style','text','Units','pixels','Position',pos, ...
            'BackgroundColor',[0.13 0.14 0.16],'ForegroundColor',col, ...
            'FontSize',13,'FontWeight','bold','HorizontalAlignment','center', ...
            'String',label);
    end

    function switchMode(~,~)
        v = get(h.mode,'Value');
        if v == 2, return; end
        obsCopy = S.obs;
        close3D([],[]);
        drawnow;
        if v == 1
            prm_robot_arm(1);
        else
            launchFBDMode();
        end
    end

    function obsEdited(~,~)
        if isempty(S.obs), return; end
        [oNew,typeChanged] = obsUIPull(h.obs,S.obs(S.obsSel));
        S.obs(S.obsSel) = oNew;
        if typeChanged
            obsUIPush(h.obs,S.obs,S.obsSel);
        else
            obsUIRefreshText(h.obs,S.obs(S.obsSel));
        end
        obstaclesChanged();
    end

    function obsSelected(~,~)
        if isempty(S.obs), return; end
        S.obsSel = get(h.obs.list,'Value');
        obsUIPush(h.obs,S.obs,S.obsSel);
    end

    function obsAdd(~,~)
        n = numel(S.obs) + 1;
        newType = obsUIAddType(h.obs);
        newC = obsSuggestedCenter(S.obs,S.obsSel,[0.0 1.0 0.8],p.posLim,n);
        S.obs(n) = obsMake(newType,newC, ...
            obsDefaultDim(newType,[0.40 0.40 0.40]),[0 0],obsPalette(n));
        S.obsSel = n;
        obsUIPush(h.obs,S.obs,S.obsSel);
        obstaclesChanged();
    end

    function obsRemove(~,~)
        if isempty(S.obs), return; end
        S.obs(S.obsSel) = [];
        if isempty(S.obs), S.obsSel=0; else, S.obsSel=min(S.obsSel,numel(S.obs)); end
        obsUIPush(h.obs,S.obs,S.obsSel);
        obstaclesChanged();
    end

    function obstaclesChanged()
        S.surfaceKey = [];
        reclassify();
        rebuildEdges();
        recomputePath();
        redrawAll();
    end

    function viewChanged(~,~)
        S.viewAng = get(h.view,'Value');
        S.workspaceView(1) = S.viewAng*180/pi;
        applyView();
    end

    function showChanged(~,~)
        S.showCObs = logical(get(h.show,'Value'));
        redrawAll();
    end

    function radiusChanged(~,~)
        S.r = get(h.radius,'Value');
        set(h.radiusText,'String',sprintf('%.2f',S.r));
        rebuildEdges();
        recomputePath();
        redrawAll();
    end

    function progressChanged(~,~)
        S.progress = get(h.progress,'Value');
        refreshProgress3();
    end

    function togglePlay3(~,~)
        if S.animOn, stopAnim3(); else, startAnim3(); end
    end

    function startAnim3()
        if S.pathType == -1, return; end
        stopAnim3();
        S.animOn = true;
        S.animDir = 1;
        S.animClock = tic;
        set(h.play,'String','|| stop');
        S.animTimer = timer('ExecutionMode','fixedSpacing','Period',p.animPeriod, ...
            'BusyMode','drop','TimerFcn',@animTick3,'Tag','PRM_TIMER');
        start(S.animTimer);
    end

    function stopAnim3()
        S.animOn = false;
        if isgraphics(f3) && isfield(h,'play') && isgraphics(h.play)
            set(h.play,'String','> play');
        end
        try
            if ~isempty(S.animTimer) && isvalid(S.animTimer)
                stop(S.animTimer); delete(S.animTimer);
            end
        catch
        end
        S.animTimer = [];
    end

    function animTick3(~,~)
        if ~isgraphics(f3) || S.pathType == -1
            stopAnim3();
            return
        end
        dt = toc(S.animClock); S.animClock = tic;
        S.progress = S.progress + S.animDir*dt/max(p.tTotal,0.5);
        if S.progress >= 1, S.progress = 1; S.animDir = -1; end
        if S.progress <= 0, S.progress = 0; S.animDir = 1; end
        set(h.progress,'Value',S.progress);
        refreshProgress3();
    end

    function refreshProgress3()
        if ~isfield(h,'curTube') || any(~isgraphics(h.curTube))
            redrawAll(); return
        end
        if toc(S.frameClock) < 0.016, return; end
        S.frameClock = tic;
        updateCurrentRobot3();
        drawThetaCharts();
        updateDetailedCursor3();
        drawnow limitrate nocallbacks
    end

    function updateCurrentRobot3()
        q = currentQ();
        [P1,P2,P3] = jointOriginsMany(q); P0 = [0 0 1];
        setTubeData(h.curTube(1),P0,P1,p.linkR);
        setTubeData(h.curTube(2),P1,P2,p.linkR);
        setTubeData(h.curTube(3),P2,P3,p.linkR);
        setSphData(h.curSph(1),P0,0.075);
        setSphData(h.curSph(2),P1,0.075);
        setSphData(h.curSph(3),P2,0.075);
        setSphData(h.curSph(4),P3,0.060);
        if isfield(h,'curDot') && isgraphics(h.curDot)
            set(h.curDot,'XData',q(1),'YData',q(2),'ZData',q(3));
        end
    end

    function start3Changed(~,~)
        candidate = S.qs; candidate(3) = get(h.start3,'Value');
        if collideGround(candidate), set(h.start3,'Value',S.qs(3)); return; end
        S.qs = candidate;
        recomputePath();
        redrawAll();
    end

    function goal3Changed(~,~)
        candidate = S.qf; candidate(3) = get(h.goal3,'Value');
        if collideGround(candidate), set(h.goal3,'Value',S.qf(3)); return; end
        S.qf = candidate;
        recomputePath();
        redrawAll();
    end

    function addPoints(~,~)
        setBusy(true);
        first = size(S.goodPts,1)+1;
        srcs = {'halton','halton_fixed','rand','image','api'};
        [U,S.sampleInfo] = prmSample(100,3,srcs{S.sampleSrc},p.noiseDir,S.sampleCursor);
        newPts = U*p.twoPi;
        S.sampleCursor = S.sampleCursor+100;
        S.pts = [S.pts;newPts];
        c = collideMany(newPts);
        S.goodPts = [S.goodPts;newPts(~c,:)];
        S.badPts = [S.badPts;newPts(c,:)];
        S.adj(end+1:size(S.goodPts,1)) = {[]};
        if S.r > 0, connectPoints(first); end
        recomputePath();
        redrawAll();
        setBusy(false);
    end

    function samplerChanged3(~,~)
        S.sampleSrc = get(h.sampler,'Value');
        S.sampleInfo = '';
    end

    function restartMap(~,~)
        S.pts = zeros(0,3); S.goodPts = zeros(0,3); S.badPts = zeros(0,3);
        S.adj = {}; S.edges = zeros(0,6); S.sampleCursor = 1;
        recomputePath();
        redrawAll();
    end

    function resetArms(~,~)
        S.qs=p.defaultQs; S.qf=p.defaultQf; S.progress=0;
        S.padTarget(:)=0; S.padFiltered(:)=0; S.padVelocity(:)=0;
        S.padWasMoving=false; S.padDrag=0; S.armDrag=0; S.cameraDrag=0;
        updateKnob(1,[0 0]); updateKnob(2,[0 0]);
        set(h.progress,'Value',0);
        set(h.start3,'Value',S.qs(3));
        set(h.goal3,'Value',S.qf(3));
        if isgraphics(f3), set(f3,'Pointer','arrow'); end
        recomputePath(); redrawAll();
        S.padLastPlan=tic; S.padLastRender=tic;
    end

    function reclassify()
        if isempty(S.pts)
            S.goodPts=zeros(0,3); S.badPts=zeros(0,3); S.adj={}; S.edges=zeros(0,6);
            return
        end
        c = collideMany(S.pts);
        S.goodPts=S.pts(~c,:); S.badPts=S.pts(c,:);
        S.adj=repmat({[]},1,size(S.goodPts,1)); S.edges=zeros(0,6);
    end

    function rebuildEdges()
        S.adj=repmat({[]},1,size(S.goodPts,1)); S.edges=zeros(0,6);
        if S.r>0 && size(S.goodPts,1)>1
            setBusy(true); connectPoints(1); setBusy(false);
        end
    end

    function connectPoints(first)
        G=S.goodPts; n=size(G,1); edgeBuffer=zeros(0,6);
        for i=max(1,first):n
            d=toroidDistMany(G,G(i,:)); d(i)=inf;
            [ds,order]=sort(d,'ascend');
            order=order(ds<=S.r);
            order=order(1:min(p.kNeighbor,numel(order)));
            for j=order(:)'
                if any(S.adj{i}==j), continue; end
                if pathOK(G(i,:),G(j,:))
                    S.adj{i}(end+1)=j; S.adj{j}(end+1)=i;
                    edgeBuffer(end+1,:)=[G(i,:) G(j,:)];
                end
            end
        end
        S.edges=[S.edges;edgeBuffer];
    end

    function recomputePath()
        S.path=[]; S.pathType=-1; S.qsn=[]; S.qfn=[]; S.totdist=0;
        S.traj=zeros(0,3); S.rawTraj=zeros(0,3); S.diag='';

        blocker=basePierced();
        if ~isempty(blocker)
            S.diag=sprintf('obstacle %s overlaps the base column, so every configuration collides',blocker);
            return
        end
        if collideMany(S.qs), S.diag='START is inside an obstacle'; return; end
        if collideMany(S.qf), S.diag='GOAL is inside an obstacle';  return; end

        if toroidDist(S.qs,S.qf)<S.r && pathOK(S.qs,S.qf)
            S.pathType=-2; S.rawTraj=[S.qs;S.qf];
            finishPath3(); return
        end
        if size(S.goodPts,1)<=5
            S.diag='roadmap is too sparse, click add 100 vertices'; return
        end
        si=connectEndpoint(S.qs); gi=connectEndpoint(S.qf);
        if ~isempty(si), S.qsn=si(1); end
        if ~isempty(gi), S.qfn=gi(1); end
        if isempty(si) && isempty(gi)
            S.diag='neither START nor GOAL reaches the roadmap, increase radius';
            return
        elseif isempty(si)
            S.diag='START cannot reach the roadmap, increase radius or add vertices';
            return
        elseif isempty(gi)
            S.diag='GOAL cannot reach the roadmap, increase radius or add vertices';
            return
        end
        ids=astarMulti(si,gi);
        if isempty(ids)
            lab=connectedComponents(S.adj);
            ns=sum(ismember(lab,unique(lab(si))));
            ng=sum(ismember(lab,unique(lab(gi))));
            S.diag=sprintf(['C_free is split: START is in a component of %d ' ...
                'nodes, GOAL in one of %d (%d components in total)'], ...
                ns,ng,max([lab;0]));
            return
        end

        Q=[S.qs;S.goodPts(ids,:);S.qf];
        for k=1:size(Q,1)-1
            if ~pathOK(Q(k,:),Q(k+1,:))
                S.diag='computed path failed local collision validation';
                return
            end
        end
        S.path=ids; S.pathType=1; S.qsn=ids(1); S.qfn=ids(end);
        S.rawTraj=Q;
        finishPath3();
    end

    function finishPath3()
        if get(h.cbSmooth,'Value')
            candidate = smoothPath3(S.rawTraj);
        else
            candidate = S.rawTraj;
        end
        if ~trajectoryOK3(candidate)
            S.path=[]; S.pathType=-1; S.traj=zeros(0,3); S.totdist=0;
            S.diag='final 3D trajectory failed dense collision certification';
            return
        end
        S.traj=candidate;
        S.totdist=sum(toroidDist(S.traj(1:end-1,:),S.traj(2:end,:)));
    end

    function smoothChanged3()

        if S.pathType~=-1 && ~isempty(S.rawTraj), finishPath3(); end
        S.progress=0; set(h.progress,'Value',0);
        redrawAll();
    end

    function Q=smoothPath3(Q)
        if size(Q,1)<3, return; end

        Q=optimalShortcut3(Q);

        for it=1:2
            if size(Q,1)<3, break; end
            cut=Q(1,:);
            for jj=1:size(Q,1)-1
                a=Q(jj,:); dv=wrapPi(Q(jj+1,:)-a);
                cut(end+1,:)=mod(a+0.25*dv,p.twoPi);
                cut(end+1,:)=mod(a+0.75*dv,p.twoPi);
            end
            cut(end+1,:)=Q(end,:);
            if ~trajectoryOK3(cut), break; end
            Q=optimalShortcut3(cut);
        end
    end

    function out=optimalShortcut3(Q)
        K=size(Q,1); best=inf(K,1); prev=zeros(K,1); best(1)=0;
        for jj=2:K
            for ii=1:jj-1
                candidate=best(ii)+toroidDist(Q(ii,:),Q(jj,:));
                if candidate<best(jj)-1e-12 && pathOK(Q(ii,:),Q(jj,:))
                    best(jj)=candidate; prev(jj)=ii;
                end
            end
        end
        if prev(K)==0, out=Q; return; end
        idx=K;
        while idx(1)>1, idx=[prev(idx(1));idx]; end
        out=Q(idx,:);
    end

    function ok=trajectoryOK3(Q)
        ok=size(Q,1)>=2 && ~any(collideMany(Q));
        if ~ok, return; end
        for jj=1:size(Q,1)-1
            if ~pathOK(Q(jj,:),Q(jj+1,:)), ok=false; return; end
        end
    end

    function name=basePierced()

        name='';
        for i = 1:numel(S.obs)
            d = obsSegDist([0 0 p.groundZ],[0 0 p.baseTop],S.obs(i));
            if d < p.baseRadius+p.clearance
                name = sprintf('#%d (%s)',i,S.obs(i).type);
                return
            end
        end
    end

    function ids=connectEndpoint(q)
        G=S.goodPts; d=toroidDistMany(G,q);
        [ds,order]=sort(d,'ascend'); ids=[];
        order=order(ds<=S.r);
        order=order(1:min(p.kNeighbor,numel(order)));
        for id=order(:)'
            if pathOK(q,G(id,:)), ids(end+1)=id; end
        end
    end

    function pth=astarMulti(starts,goals)
        G=S.goodPts; n=size(G,1); s=n+1; t=n+2;
        A=[S.adj(:);{starts(:)'};{goals(:)'}];
        for id=starts(:)', A{id}(end+1)=s; end
        for id=goals(:)', A{id}(end+1)=t; end
        allIds=astarGeneric(A,[G;S.qs;S.qf],s,t,@toroidDist);
        pth=allIds(allIds<=n);
    end

    function ok=pathOK(a,b)
        d=toroidDist(a,b);
        if any(collideMany([a;b])), ok=false; return; end
        if d<=p.delta, ok=true; return; end
        n=ceil(d/p.delta); u=(1:n-1)'/n;
        Q=mod(a+u.*wrapPi(b-a),p.twoPi);
        ok=~any(collideMany(Q));
    end

    function c=collideMany(Q)
        c = collideGround(Q) | collideSelf3(Q);
        for i = 1:numel(S.obs)
            c = c | collideOneObstacle(Q,S.obs(i));
        end
    end

    function c=collideSelf3(Q)

        [P1,P2,P3]=jointOriginsMany(Q);
        N=size(Q,1);
        P0=repmat([0 0 1],N,1);
        B0=repmat([0 0 p.groundZ],N,1);
        B1=repmat([0 0 p.baseTop],N,1);
        baseGap=p.baseRadius+p.linkR+p.clearance;
        selfGap=2*p.linkR+p.selfClearance;
        c = segSegDist(P1,P2,B0,B1) < baseGap | ...
            segSegDist(P2,P3,B0,B1) < baseGap | ...
            segSegDist(P0,P1,P2,P3) < selfGap;
    end

    function c=collideOneObstacle(Q,o)
        [P1,P2,P3]=jointOriginsMany(Q);
        N=size(Q,1);
        B0=repmat([0 0 p.groundZ],N,1); B1=repmat([0 0 p.baseTop],N,1);
        P0=repmat([0 0 1],N,1);
        linkGap = p.linkR + p.clearance;
        c = obsSegDist(P0,P1,o) < linkGap | ...
            obsSegDist(P1,P2,o) < linkGap | ...
            obsSegDist(P2,P3,o) < linkGap | ...
            obsSegDist(B0,B1,o) < p.baseRadius + p.clearance;
    end

    function c=collideGround(Q)
        [P1,P2,P3]=jointOriginsMany(Q);
        minZ=min([P1(:,3) P2(:,3) P3(:,3)],[],2);
        c=minZ < p.groundZ+p.linkR+p.clearance;
    end

    function [P1,P2,P3]=jointOriginsMany(Q)
        t1=Q(:,1); t2=Q(:,2); t3=Q(:,3);
        P1=[cos(t1) sin(t1) ones(size(t1))];
        P2=P1+[cos(t1).*cos(t2),sin(t1).*cos(t2),sin(t2)];
        P3=P2+[cos(t1).*cos(t2).*cos(t3)+sin(t1).*sin(t3), ...
               sin(t1).*cos(t2).*cos(t3)-cos(t1).*sin(t3), ...
               sin(t2).*cos(t3)];
    end

    function redrawAll()
        if S.pathType==-1
            S.progress=0;
            stopAnim3();
            set(h.progress,'Value',0,'Enable','off', ...
                'TooltipString','Progress is available after a collision-free path is found.');
            set(h.play,'Enable','off');
        else
            set(h.progress,'Enable','on', ...
                'TooltipString','Drag to move the robot along the collision-free path.');
            set(h.play,'Enable','on');
        end
        drawWorkspace();
        drawConfigSpace();
        drawThetaCharts();
        if isfield(h,'reportFig3') && isgraphics(h.reportFig3)
            populateDetailedThetaPlot3();
        end
        set(h.startText,'String',sprintf('START  %.2f   %.2f   %.2f rad',S.qs));
        set(h.goalText,'String',sprintf('GOAL   %.2f   %.2f   %.2f rad',S.qf));
        startBad=collideMany(S.qs); goalBad=collideMany(S.qf);
        if S.pathType==-1
            if ~isempty(S.diag), reason=S.diag;
            elseif startBad, reason='START is inside an obstacle';
            elseif goalBad, reason='GOAL is inside an obstacle';
            else, reason='no path found yet'; end
            msg={sprintf('Progress locked: %s',reason); ...
                 sprintf('free V=%d | blocked=%d',size(S.goodPts,1),size(S.badPts,1)); ...
                 sprintf('obstacles: %d',numel(S.obs))};
        else
            if get(h.cbSmooth,'Value')
                pathInfo=sprintf('waypoints %d -> %d after smoothing', ...
                    size(S.rawTraj,1),size(S.traj,1));
                modeInfo='Mode: SMOOTHED PATH (collision-certified shortcuts)';
            else
                pathInfo=sprintf('waypoints=%d, all original PRM nodes retained', ...
                    size(S.rawTraj,1));
                modeInfo='Mode: FOLLOW PRM NODES (smoothing OFF)';
            end
            msg={sprintf('%s   |   length = %.3f rad',modeInfo,S.totdist); ...
                 sprintf('V=%d   E=%d   %s',size(S.goodPts,1),size(S.edges,1),pathInfo); ...
                 sprintf('collision-certified   obstacles: %d   %s',numel(S.obs),S.sampleInfo)};
        end
        set(h.info,'String',msg);
        drawnow limitrate nocallbacks
    end

    function drawThetaCharts()
        labels = {'\theta_1','\theta_2','\theta_3'};
        if S.pathType == -1
            thetaPlot(h.axT,[],labels,[true true true],[true true true],p.tTotal,0,[]);
        else
            Qp = densifyTrajectory3(S.traj,121);
            tp = linspace(0,p.tTotal,size(Qp,1))';
            thetaPlot(h.axT,Qp,labels,[true true true],[true true true], ...
                p.tTotal,S.progress,currentQ(),tp);
        end
    end

    function Qd = densifyTrajectory3(Q,N)
        d = toroidDist(Q(1:end-1,:),Q(2:end,:));
        cum = [0; cumsum(d)]; total = cum(end);
        if total < 1e-12, Qd = repmat(Q(1,:),N,1); return; end
        sv = linspace(0,total,N)'; Qd = zeros(N,3);
        for ii = 1:N
            jj = find(cum <= sv(ii),1,'last');
            jj = min(max(jj,1),size(Q,1)-1);
            u = (sv(ii)-cum(jj))/max(d(jj),1e-12);
            Qd(ii,:) = mod(Q(jj,:) + u*wrapPi(Q(jj+1,:)-Q(jj,:)),p.twoPi);
        end
    end

    function openDetailedThetaPlot3(~,~)
        old = findall(groot,'Type','figure','Name','3D robot - detailed joint report');
        if ~isempty(old), delete(old); end
        fr = figure('Name','3D robot - detailed joint report','NumberTitle','off', ...
            'Color','w','Position',[100 80 780 680],'MenuBar','figure','ToolBar','figure');
        ar = gobjects(1,3);
        y0 = [0.66 0.39 0.12];
        for jj = 1:3
            ar(jj) = axes('Parent',fr,'Units','normalized', ...
                'Position',[0.14 y0(jj) 0.80 0.20]);
        end
        h.reportFig3 = fr;
        h.reportAxes3 = ar;
        h.reportHeader3 = annotation(fr,'textbox',[0.07 0.925 0.88 0.06], ...
            'String','','Interpreter','tex','EdgeColor','none', ...
            'HorizontalAlignment','center','Color',[0.08 0.08 0.08], ...
            'FontSize',12,'FontWeight','bold');
        h.reportFooter3 = annotation(fr,'textbox',[0.10 0.01 0.84 0.045], ...
            'String','','EdgeColor','none','HorizontalAlignment','center', ...
            'Color',[0.08 0.08 0.08],'FontSize',10);
        populateDetailedThetaPlot3();
        if S.pathType ~= -1 && ~S.animOn, startAnim3(); end
    end

    function populateDetailedThetaPlot3()
        if ~isfield(h,'reportFig3') || ~isgraphics(h.reportFig3), return; end
        Qr = S.traj;
        if get(h.cbSmooth,'Value')
            stateLine = 'smoothed, collision-certified PRM trajectory';
        else
            stateLine = 'original PRM node-by-node trajectory';
        end
        if isempty(Qr)
            Qr = [S.qs;S.qf];
            stateLine = 'START / GOAL preview - no PRM path yet';
        else
            Qr = densifyTrajectory3(Qr,241);
        end
        tr = linspace(0,p.tTotal,size(Qr,1))';
        [h.reportCursorLine3,h.reportCursorDot3,h.reportCurve3] = thetaPlot( ...
            h.reportAxes3,Qr,{'\theta_1','\theta_2','\theta_3'}, ...
            [true true true],[true true true],p.tTotal,S.progress,currentQ(),tr);
        for jj = 1:3
            set(h.reportAxes3(jj),'XTick',linspace(0,p.tTotal,7), ...
                'XTickLabelMode','auto','FontSize',10,'LineWidth',0.8);
            hideAxesChrome(h.reportAxes3(jj));
        end
        set(h.reportHeader3,'String',{sprintf('Three-joint trajectory — %s',stateLine); ...
            '\theta_1, \theta_2 and \theta_3 are shown in degrees'});
        set(h.reportFooter3,'String',sprintf(['START  [%.1f%c, %.1f%c, %.1f%c]     ' ...
            'GOAL  [%.1f%c, %.1f%c, %.1f%c]'], ...
            rad2deg(S.qs(1)),char(176),rad2deg(S.qs(2)),char(176), ...
            rad2deg(S.qs(3)),char(176),rad2deg(S.qf(1)),char(176), ...
            rad2deg(S.qf(2)),char(176),rad2deg(S.qf(3)),char(176)));
    end

    function updateDetailedCursor3()
        if ~isfield(h,'reportFig3') || ~isgraphics(h.reportFig3) || ...
                ~isfield(h,'reportCurve3') || any(~isgraphics(h.reportCurve3)), return; end
        tc = S.progress*p.tTotal;
        for jj = 1:3
            xx = get(h.reportCurve3(jj),'XData'); yy = get(h.reportCurve3(jj),'YData');
            yc = interp1(xx,yy,tc,'linear','extrap'); yl = ylim(h.reportAxes3(jj));
            set(h.reportCursorLine3(jj),'XData',[tc tc],'YData',yl);
            set(h.reportCursorDot3(jj),'XData',tc,'YData',yc);
        end
    end

    function drawWorkspace()
        ax=h.axW; cla(ax); hold(ax,'on');
        drawGroundPlane(ax,[-3.5 3.5],[-3.5 3.5],p.groundZ,[0.90 0.92 0.95],0.72);
        drawWireBox(ax,[-3.5 3.5],[-3.5 3.5],[p.groundZ 3.4],[0.70 0.74 0.81],0.65);
        if S.pathType~=-1 && size(S.traj,1)>1
            Qpath=densifyTrajectory3(S.traj,241);
            [~,~,tipPath]=jointOriginsMany(Qpath);
            plot3(ax,tipPath(:,1),tipPath(:,2),tipPath(:,3),'-', ...
                'Color',[0.82 0.08 0.78],'LineWidth',2.8, ...
                'DisplayName','Planned end-effector path');
            if ~get(h.cbSmooth,'Value')

                [~,~,tipNodes]=jointOriginsMany(S.rawTraj);
                scatter3(ax,tipNodes(:,1),tipNodes(:,2),tipNodes(:,3), ...
                    34,'o','MarkerFaceColor',[1.00 0.73 0.08], ...
                    'MarkerEdgeColor',[0.45 0.18 0.02],'LineWidth',0.8, ...
                    'DisplayName','Original PRM waypoints');
            end
        end
        drawRobot3(ax,S.qs,[0.20 0.75 0.42],0.18);
        drawRobot3(ax,S.qf,[0.92 0.32 0.36],0.18);
        drawTube(ax,[0 0 p.groundZ],[0 0 p.baseTop],p.baseRadius,[0.35 0.21 0.12],1);
        drawSphere(ax,[0 0 1],0.105,[0.35 0.21 0.12],1);
        h.curTube = gobjects(1,3); h.curSph = gobjects(1,4);
        for kk = 1:3, h.curTube(kk) = newTube(ax,[0.46 0.27 0.14],1); end
        for kk = 1:4, h.curSph(kk)  = newSph(ax,[0.46 0.27 0.14],1); end
        updateCurrentRobot3();
        for i = 1:numel(S.obs)
            drawObstacle(ax,S.obs(i),1);
        end
        [~,~,tipS]=jointOriginsMany(S.qs);
        [~,~,tipG]=jointOriginsMany(S.qf);
        h.startTip=scatter3(ax,tipS(1),tipS(2),tipS(3),110,'o','filled', ...
            'MarkerFaceColor',[0.10 0.82 0.42],'MarkerEdgeColor','w', ...
            'LineWidth',1.5,'Tag','PRM_START_TIP','PickableParts','all');
        h.goalTip=scatter3(ax,tipG(1),tipG(2),tipG(3),110,'o','filled', ...
            'MarkerFaceColor',[0.96 0.25 0.32],'MarkerEdgeColor','w', ...
            'LineWidth',1.5,'Tag','PRM_GOAL_TIP','PickableParts','all');
        daspect(ax,[1 1 1]);
        set(ax,'XLim',[-3.5 3.5],'YLim',[-3.5 3.5],'ZLim',[p.groundZ 3.4], ...
            'Color',[0.98 0.98 0.99],'XTick',[],'YTick',[],'ZTick',[], ...
            'Box','off','XColor','none','YColor','none','ZColor','none', ...
            'SortMethod','depth');
        trySet(ax,'ClippingStyle','rectangle');
        title(ax,'3-link robot workspace','FontSize',12);
        light('Parent',ax,'Position',[1 -1 3]); lighting(ax,'gouraud');
        applyView(); hold(ax,'off');
    end

    function applyView()
        if ~isgraphics(h.axW), return; end
        view(h.axW,S.workspaceView);
    end

    function drawRobot3(ax,q,col,alpha)
        [P1,P2,P3]=jointOriginsMany(q);
        P0=[0 0 1];
        drawTube(ax,P0,P1,p.linkR,col,alpha);
        drawTube(ax,P1,P2,p.linkR,col,alpha);
        drawTube(ax,P2,P3,p.linkR,col,alpha);
        drawSphere(ax,P0,0.075,col,alpha);
        drawSphere(ax,P1,0.075,col,alpha);
        drawSphere(ax,P2,0.075,col,alpha);
        drawSphere(ax,P3,0.060,col,alpha);
    end

    function q=currentQ()
        q=S.qs;
        if S.pathType==-1 || ~isfield(S,'traj') || size(S.traj,1)<2, return; end
        Q=S.traj;
        d=toroidDist(Q(1:end-1,:),Q(2:end,:));
        total=sum(d);
        if total<1e-9, return; end
        target=S.progress*total; acc=0; k=1;
        while k<numel(d)&&acc+d(k)<target, acc=acc+d(k); k=k+1; end
        q=mod(Q(k,:)+((target-acc)/max(d(k),1e-9))*wrapPi(Q(k+1,:)-Q(k,:)),p.twoPi);
    end

    function drawConfigSpace()
        ax=h.axC; cla(ax); hold(ax,'on');
        if S.showCObs, drawConfigurationObstacles(ax); end
        if ~isempty(S.edges)
            drawSegments3(ax,S.edges(:,1:3),S.edges(:,4:6),[0.62 0.42 0.24],0.45);
        end
        if ~isempty(S.badPts)
            scatter3(ax,S.badPts(:,1),S.badPts(:,2),S.badPts(:,3),12,[0.95 0.15 0.12],'filled');
        end
        if ~isempty(S.goodPts)
            scatter3(ax,S.goodPts(:,1),S.goodPts(:,2),S.goodPts(:,3),16,[0.05 0.75 0.25],'filled');
        end
        if S.pathType~=-1 && isfield(S,'traj') && size(S.traj,1)>1
            if get(h.cbSmooth,'Value') && size(S.rawTraj,1)>1
                drawToroidSegs3(ax,S.rawTraj(1:end-1,:),S.rawTraj(2:end,:), ...
                    [0.55 0.55 0.60],1.0,'--');
            end
            drawToroidSegs3(ax,S.traj(1:end-1,:),S.traj(2:end,:),[1 0 1],3,'-');
            if ~get(h.cbSmooth,'Value')
                scatter3(ax,S.rawTraj(:,1),S.rawTraj(:,2),S.rawTraj(:,3), ...
                    42,'o','MarkerFaceColor',[1.00 0.73 0.08], ...
                    'MarkerEdgeColor',[0.30 0.12 0.02],'LineWidth',0.9, ...
                    'Tag','PRM_RAW_WAYPOINTS');
            end
        end
        drawConfigMarker(ax,S.qs,[0.10 0.75 0.35]);
        drawConfigMarker(ax,S.qf,[0.95 0.22 0.30]);
        q=currentQ();
        h.curDot=scatter3(ax,q(1),q(2),q(3),65,[0.15 0.35 1],'filled', ...
            'MarkerEdgeColor','w','Tag','PRM3_CURC');
        set(ax,'XLim',[0 p.twoPi],'YLim',[0 p.twoPi],'ZLim',[0 p.twoPi], ...
            'Color',[0.04 0.045 0.055],'XColor',[.85 .87 .92], ...
            'YColor',[.85 .87 .92],'ZColor',[.85 .87 .92],'Box','on','FontSize',8);
        xlabel(ax,'\theta_1'); ylabel(ax,'\theta_2'); zlabel(ax,'\theta_3');
        title(ax,'3D robot configuration space','Color',[.92 .94 .98],'FontSize',11);
        view(ax,S.configView); grid(ax,'on'); axis(ax,'vis3d'); hold(ax,'off');
    end

    function drawConfigMarker(ax,q,col)
        scatter3(ax,q(1),q(2),q(3),120,'o','MarkerEdgeColor',col,'LineWidth',2);
        scatter3(ax,q(1),q(2),q(3),35,'+','MarkerEdgeColor',col,'LineWidth',1.5);
    end

    function drawSegments3(ax,A,B,col,lw)
        B=A+wrapPi(B-A); n=size(A,1);
        X=[A(:,1)';B(:,1)';nan(1,n)]; Y=[A(:,2)';B(:,2)';nan(1,n)];
        Z=[A(:,3)';B(:,3)';nan(1,n)];
        plot3(ax,X(:),Y(:),Z(:),'-','Color',col,'LineWidth',lw,'Clipping','on');
    end

    function drawConfigurationObstacles(ax)
        key=obsKey(S.obs);
        if isempty(S.surfaceKey)||~isequal(key,S.surfaceKey)
            setBusy(true);
            lin=linspace(0,p.twoPi,p.surfaceN);
            [A1,A2,A3]=meshgrid(lin,lin,lin);
            Q=[A1(:) A2(:) A3(:)];
            S.surfaces = cell(1,numel(S.obs)+1);
            for i=1:numel(S.obs)
                m=reshape(collideOneObstacle(Q,S.obs(i)),size(A1));
                S.surfaces{i}=isosurface(lin,lin,lin,double(m),0.5);
            end
            mG=reshape(collideGround(Q),size(A1));
            S.surfaces{end}=isosurface(lin,lin,lin,double(mG),0.5);
            S.surfaceKey=key;
            setBusy(false);
        end
        for i=1:numel(S.surfaces)
            sf=S.surfaces{i};
            if isempty(sf)||isempty(sf.vertices), continue; end
            if i<=numel(S.obs), col=S.obs(i).color; else, col=[0.55 0.58 0.64]; end
            patch('Parent',ax,'Faces',sf.faces,'Vertices',sf.vertices, ...
                'FaceColor',col,'FaceAlpha',0.20,'EdgeColor','none');
        end
    end

    function [padId,xy]=padHit()
        padId=0; xy=[];
        ax=axesAtPointer(f3,[h.axStart h.axGoal]);
        if isequal(ax,h.axStart), padId=1;
        elseif isequal(ax,h.axGoal), padId=2; end
        if padId>0, xy=padPoint(padId); if isempty(xy), padId=0; end, end
    end

    function xy=padPoint(id)
        if id==1, ax=h.axStart; else, ax=h.axGoal; end
        cp=get(ax,'CurrentPoint'); xy=cp(1,1:2);
        if any(~isfinite(xy))||norm(xy)>1.25, xy=[]; return; end
        if norm(xy)>1, xy=xy/norm(xy); end
    end

    function mouseDown(~,~)
        [id,xy]=padHit();
        if id>0
            S.padDrag=id; S.padTarget(id,:)=xy; updateKnob(id,xy);
            return
        end
        obj=currentHitObject(); tag='';
        if ~isempty(obj) && isgraphics(obj)
            try, tag=get(obj,'Tag'); catch, tag=''; end
        end
        primaryClick=strcmp(get(f3,'SelectionType'),'normal');
        if primaryClick && strcmp(tag,'PRM_START_TIP')
            beginArmDrag(1); return
        elseif primaryClick && strcmp(tag,'PRM_GOAL_TIP')
            beginArmDrag(2); return
        end
        ax=currentHitAxes();
        if isempty(ax) && primaryClick
            armHit=pickArmNearCursor();
            if armHit>0, beginArmDrag(armHit); return; end
        end
        if isequal(ax,h.axW)
            if primaryClick
                armHit=pickArmNearCursor();
                if armHit>0, beginArmDrag(armHit); return; end
            end
            S.cameraDrag=1;
        elseif isequal(ax,h.axC), S.cameraDrag=2;
        else, return
        end
        S.lastCameraAxis=S.cameraDrag;
        if strcmp(get(f3,'SelectionType'),'open')
            resetCamera(S.cameraDrag);
            S.cameraDrag=0;
            return
        end
        S.cameraLastPoint=get(f3,'CurrentPoint');
        set(f3,'Pointer','fleur');
    end

    function mouseMove(~,~)
        if S.padDrag~=0
            xy=padPoint(S.padDrag);
            if ~isempty(xy), S.padTarget(S.padDrag,:)=xy; updateKnob(S.padDrag,xy); end
            return
        end
        if S.armDrag~=0
            target=cursorPlaneTarget();
            if ~isempty(target)
                if S.armDrag==1
                    S.qs=solveIKDLS(S.qs,target);
                    set(h.start3,'Value',S.qs(3));
                else
                    S.qf=solveIKDLS(S.qf,target);
                    set(h.goal3,'Value',S.qf(3));
                end
                if toc(S.padLastPlan)>=.12, recomputePath(); S.padLastPlan=tic; end
                if toc(S.padLastRender)>=.07, redrawAll(); S.padLastRender=tic; end
            end
            return
        end
        if S.cameraDrag==0, return; end
        pt=get(f3,'CurrentPoint'); dp=pt-S.cameraLastPoint;
        S.cameraLastPoint=pt;
        if S.cameraDrag==1
            S.workspaceView=orbitView(S.workspaceView,dp);
            S.viewAng=(mod(S.workspaceView(1)+90,360)-90)*pi/180;
            lo=get(h.view,'Min'); hi=get(h.view,'Max');
            set(h.view,'Value',min(max(S.viewAng,lo),hi));
            view(h.axW,S.workspaceView);
        else
            S.configView=orbitView(S.configView,dp);
            view(h.axC,S.configView);
        end
        drawnow limitrate nocallbacks
    end

    function mouseUp(~,~)
        armWasDragging=S.armDrag~=0;
        if S.padDrag~=0
            id=S.padDrag; S.padTarget(id,:)=[0 0]; updateKnob(id,[0 0]); S.padDrag=0;
        end
        S.armDrag=0;
        S.cameraDrag=0;
        if isgraphics(f3), set(f3,'Pointer','arrow'); end
        if armWasDragging
            recomputePath(); redrawAll();
            S.padLastPlan=tic; S.padLastRender=tic;
        end
    end

    function obj=currentHitObject()
        try, obj=hittest(f3); catch, obj=get(f3,'CurrentObject'); end
    end

    function ax=currentHitAxes()
        ax=axesAtPointer(f3,[h.axW h.axC],24);
    end

    function beginArmDrag(whichArm)
        S.armDrag=whichArm; S.cameraDrag=0;
        S.padTarget(:)=0; S.padFiltered(:)=0; S.padVelocity(:)=0;
        S.padWasMoving=false;
        if whichArm==1, q=S.qs; else, q=S.qf; end
        [~,~,tip]=jointOriginsMany(q);
        n=campos(h.axW)-camtarget(h.axW);
        if norm(n)<1e-12, n=[0 0 1]; else, n=n/norm(n); end
        S.armPlanePoint=tip;
        S.armPlaneNormal=n;
        set(f3,'Pointer','crosshair');
    end

    function whichArm=pickArmNearCursor()
        whichArm=0;
        cp=get(h.axW,'CurrentPoint'); r0=cp(1,:); ray=cp(2,:)-cp(1,:);
        rayNorm=norm(ray);
        if rayNorm<1e-12, return; end
        [~,~,tipS]=jointOriginsMany(S.qs);
        [~,~,tipG]=jointOriginsMany(S.qf);
        tips=[tipS;tipG];
        rayCross=cross(tips-r0,repmat(ray,2,1),2);
        d=sqrt(sum(rayCross.^2,2))/rayNorm;
        tol=armPickTolerance(h.axW);
        [dm,k]=min(d);
        if dm<=tol, whichArm=k; end
    end

    function target=cursorPlaneTarget()
        cp=get(h.axW,'CurrentPoint'); r0=cp(1,:); ray=cp(2,:)-cp(1,:);
        den=dot(ray,S.armPlaneNormal);
        if abs(den)<1e-10, target=[]; return; end
        t=dot(S.armPlanePoint-r0,S.armPlaneNormal)/den;
        target=r0+t*ray;
        target=max(min(target,[3.45 3.45 3.35]),[-3.45 -3.45 p.groundZ+p.linkR]);
    end

    function q=solveIKDLS(q,target)
        epsJ=1e-4; lambda=0.06;
        for iter=1:24
            [~,~,tip]=jointOriginsMany(q);
            err=target-tip; oldNorm=norm(err);
            if oldNorm<2e-3, break; end
            J=zeros(3,3);
            for k=1:3
                qd=q; qd(k)=mod(qd(k)+epsJ,p.twoPi);
                [~,~,tipD]=jointOriginsMany(qd);
                J(:,k)=((tipD-tip)/epsJ)';
            end
            dq=J'*((J*J'+lambda^2*eye(3))\err');
            if norm(dq)>0.22, dq=dq*(0.22/norm(dq)); end
            improved=false; scale=1;
            for ls=1:5
                candidate=mod(q+(scale*dq)',p.twoPi);
                [~,~,tipC]=jointOriginsMany(candidate);
                if ~collideGround(candidate) && norm(target-tipC)<oldNorm
                    q=candidate; improved=true; break
                end
                scale=scale/2;
            end
            if ~improved, break; end
        end
    end

    function resetCamera(whichAxis)
        if whichAxis==1
            S.workspaceView=p.defaultView;
            S.viewAng=S.workspaceView(1)*pi/180;
            lo=get(h.view,'Min'); hi=get(h.view,'Max');
            set(h.view,'Value',min(max(S.viewAng,lo),hi));
            view(h.axW,S.workspaceView);
            camva(h.axW,'auto');
        else
            S.configView=p.defaultView;
            view(h.axC,S.configView);
            camva(h.axC,'auto');
        end
        drawnow limitrate nocallbacks
    end

    function mouseWheel(~,evt)
        ax=currentHitAxes();
        if isempty(ax)
            if S.lastCameraAxis==1, ax=h.axW; else, ax=h.axC; end
        elseif isequal(ax,h.axW), S.lastCameraAxis=1;
        elseif isequal(ax,h.axC), S.lastCameraAxis=2;
        else, return
        end
        mods=get(f3,'CurrentModifier');
        steps=evt.VerticalScrollCount;
        if any(strcmp(mods,'shift')) || any(strcmp(mods,'alt')) || any(strcmp(mods,'control'))
            if any(strcmp(mods,'shift')), dp=[6*steps 0]; else, dp=[0 6*steps]; end
            if isequal(ax,h.axW)
                S.workspaceView=orbitView(S.workspaceView,dp);
                S.viewAng=(mod(S.workspaceView(1)+90,360)-90)*pi/180;
                lo=get(h.view,'Min'); hi=get(h.view,'Max');
                set(h.view,'Value',min(max(S.viewAng,lo),hi));
                view(h.axW,S.workspaceView);
            else
                S.configView=orbitView(S.configView,dp);
                view(h.axC,S.configView);
            end
        else
            boundedCamzoom(ax,1.12^(-steps));
        end
        drawnow limitrate nocallbacks
    end

    function updateKnob(id,xy)
        if id==1, knob=h.startKnob; else, knob=h.goalKnob; end
        if isgraphics(knob), set(knob,'XData',xy(1),'YData',xy(2)); end
    end

    function padTick(~,~)
        if ~isgraphics(f3), return; end
        dt=min(max(toc(S.padLastTick),.001),.06); S.padLastTick=tic;
        alpha=1-exp(-2*pi*p.padCutoffHz*dt); changed=false;
        for id=1:2
            xy=S.padTarget(id,:); r=norm(xy);
            if r<=p.padDeadZone, shaped=[0 0];
            else, shaped=(xy/r)*((r-p.padDeadZone)/(1-p.padDeadZone)); end
            S.padFiltered(id,:)=S.padFiltered(id,:)+alpha*(shaped-S.padFiltered(id,:));
            desired=S.padFiltered(id,:).*p.padMaxVel;
            maxStep=p.padMaxAccel*dt;
            dv=min(max(desired-S.padVelocity(id,:),-maxStep),maxStep);
            S.padVelocity(id,:)=S.padVelocity(id,:)+dv;
            if norm(S.padVelocity(id,:))>1e-4
                if id==1
                    candidate=S.qs;
                    candidate(1:2)=mod(candidate(1:2)+S.padVelocity(id,:)*dt,p.twoPi);
                    if ~collideGround(candidate), S.qs=candidate; changed=true; end
                else
                    candidate=S.qf;
                    candidate(1:2)=mod(candidate(1:2)+S.padVelocity(id,:)*dt,p.twoPi);
                    if ~collideGround(candidate), S.qf=candidate; changed=true; end
                end
            end
        end
        if changed
            S.padWasMoving=true;
            if toc(S.padLastPlan)>=.12, recomputePath(); S.padLastPlan=tic; end
            if toc(S.padLastRender)>=.07, redrawAll(); S.padLastRender=tic; end
        elseif S.padWasMoving
            recomputePath(); redrawAll(); S.padWasMoving=false;
            S.padLastPlan=tic; S.padLastRender=tic;
        end
    end

    function setBusy(on)
        if ~isgraphics(f3), return; end
        if on, set(f3,'Pointer','watch'); else, set(f3,'Pointer','arrow'); end
        drawnow limitrate
    end

    function close3D(~,~)
        stopAnim3();
        try
            if isfield(S,'padTimer')&&isvalid(S.padTimer)
                stop(S.padTimer); delete(S.padTimer);
            end
        catch
        end
        if isfield(h,'reportFig3') && isgraphics(h.reportFig3)
            delete(h.reportFig3);
        end
        if isgraphics(f3), delete(f3); end
    end
end

