        D = load(p.defaultsFile);
        q0 = D.startPose(:)';
        if numel(q0) == 4 && all(isfinite(q0)) && q0(1) >= 0 && q0(1) <= p.d1Max && ...
                all(q0(3:4) >= p.phiLim(1)) && all(q0(3:4) <= p.phiLim(2))
            q0(2) = mod(q0(2),p.twoPi);
            p.poseStart = q0;
        end
        if isfield(D,'goalPose')
            q1 = D.goalPose(:)';
            if numel(q1) == 4 && all(isfinite(q1)) && q1(1) >= 0 && q1(1) <= p.d1Max
                q1(2) = mod(q1(2),p.twoPi);
                p.poseGoal = q1;
            end
        end
        if isfield(D,'homePose')
            q2 = D.homePose(:)';
            if numel(q2) == 4 && all(isfinite(q2)) && q2(1) >= 0 && q2(1) <= p.d1Max
                q2(2) = mod(q2(2),p.twoPi);
                p.poseHome = q2;
            end
        end
        if isfield(D,'armMode') && isscalar(D.armMode) && ...
                D.armMode >= 1 && D.armMode <= numel(p.armModes)
            p.armMode = round(D.armMode);
        elseif isfield(D,'pairArms') && isscalar(D.pairArms) && D.pairArms
            p.armMode = 4;
        end
        if isfield(D,'clearance') && isnumeric(D.clearance) && ...
                isscalar(D.clearance) && isfinite(D.clearance)
            p.clearance = min(max(double(D.clearance),0),100);
        end
    catch

    end
end
