    'Min',mn,'Max',mx,'Value',min(max(val,mn),mx),'Callback',cb);
end

function hh = mkNumericEdit(par,pos,str,slider,cb)

hh = uicontrol(par,'Style','edit','Units','pixels','Position',pos, ...
    'String',str,'BackgroundColor',[0.09 0.10 0.12], ...
    'ForegroundColor',[0.96 0.97 1.00],'HorizontalAlignment','center', ...
    'FontSize',8,'UserData',struct('slider',slider,'callback',cb), ...
    'Callback',@numericEditToSlider);
end

function numericEditToSlider(src,~)

cfg = get(src,'UserData');
value = str2double(get(src,'String'));
if ~isfinite(value)
    set(src,'String',sprintf('%.3g',get(cfg.slider,'Value')));
    return
end
value = min(max(value,get(cfg.slider,'Min')),get(cfg.slider,'Max'));
set(cfg.slider,'Value',value);
set(src,'String',sprintf('%.3g',value));
feval(cfg.callback,src,[]);
end

function centerPopupText(varargin)

for a = 1:numel(varargin)
    hPop = varargin{a};
    if ~isgraphics(hPop), continue; end
    strs = get(hPop,'String');
    if ischar(strs), strs = cellstr(strs); end
    if isempty(strs), continue; end
    pos = get(hPop,'Position');
    frameW = pos(3);
    arrowW = 28;
    if frameW <= arrowW + 20, continue; end
    probe = uicontrol(get(hPop,'Parent'),'Style','text','Units','pixels', ...
        'Visible','off','Position',[1 1 10 10], ...
        'FontName',get(hPop,'FontName'),'FontSize',get(hPop,'FontSize'), ...
        'FontWeight',get(hPop,'FontWeight'));
    wSp = (uiTextWidth(probe,'|          |') - uiTextWidth(probe,'||'))/10;
    if ~isfinite(wSp) || wSp <= 0, wSp = 3; end
    for k = 1:numel(strs)
        t = strtrim(strs{k});
        textW = uiTextWidth(probe,t);

        padPx = max(0,(frameW-textW)/2);
        padPx = min(padPx,max(0,frameW-arrowW-textW));
        nSp = round(padPx/wSp);
        strs{k} = [repmat(' ',1,max(nSp,0)) t];
    end
    delete(probe);
    set(hPop,'String',strs);
end
end

function w = uiTextWidth(probe,str)

set(probe,'String',str);
e = get(probe,'Extent');
w = e(3);
end

function hh = mkLabel(par, pos, str, align)

if nargin < 4 || isempty(align), align = 'center'; end
pos(4) = max(pos(4),17);
if isprop(par,'BackgroundColor'), bg = get(par,'BackgroundColor');
else,                             bg = get(par,'Color'); end
hh = uicontrol(par,'Style','text','Units','pixels','Position',pos, ...
    'String',str,'BackgroundColor',bg, ...
    'ForegroundColor',[0.94 0.95 0.98],'HorizontalAlignment',align, ...
    'FontSize',9);
end

function knob = makeCircularPad(ax,padColor,lab1,lab2)
if nargin < 3, lab1 = 'theta_1'; end
if nargin < 4, lab2 = 'theta_2'; end
cla(ax);
hold(ax,'on');
th = linspace(0,2*pi,160);
patch(ax,cos(th),sin(th),[0.17 0.19 0.23], ...
    'EdgeColor',[0.48 0.55 0.68],'LineWidth',1.8,'HitTest','on');
plot(ax,[-1 1],[0 0],'-','Color',[0.32 0.36 0.43],'LineWidth',0.9);
plot(ax,[0 0],[-1 1],'-','Color',[0.32 0.36 0.43],'LineWidth',0.9);
plot(ax,0.12*cos(th),0.12*sin(th),'--','Color',[0.46 0.49 0.56]);
knob = plot(ax,0,0,'o','MarkerSize',18,'LineWidth',2, ...
    'MarkerFaceColor',padColor,'MarkerEdgeColor',[0.98 0.98 1.00],'HitTest','on');
text(ax,0.93,-0.10,lab1,'FontSize',8,'Color',[0.70 0.74 0.82], ...
    'HorizontalAlignment','right','VerticalAlignment','top','HitTest','off');
text(ax,0.08,0.93,lab2,'FontSize',8,'Color',[0.70 0.74 0.82], ...
    'HorizontalAlignment','left','VerticalAlignment','top','HitTest','off');
axis(ax,'equal');
set(ax,'XLim',[-1.08 1.08],'YLim',[-1.08 1.08], ...
    'XTick',[],'YTick',[],'Color','none','Box','off','Visible','off');
hold(ax,'off');
end

function hideAxesChrome(ax)
try
    ax.Toolbar.Visible = 'off';
catch
    try, axtoolbar(ax,{}); catch, end
end
try, disableDefaultInteractivity(ax); catch, end
end

function v = orbitView(v,dp)
v(1) = mod(v(1) - 0.35*dp(1) + 180,360) - 180;
v(2) = min(max(v(2) - 0.35*dp(2),-89),89);
end

function d = toroidDist(q1, q2)
a = abs(q1 - q2);
a = min(a, 2*pi - a);
d = sqrt(sum(a.^2,2));
end

function d = toroidDistMany(A, q)
a = abs(A - q);
a = min(a, 2*pi - a);
d = sqrt(sum(a.^2,2));
end

function q = toroidPt(q1, q2, t)
q = mod(q1 + t*wrapPi(q2 - q1), 2*pi);
end

function drawToroidSegs(ax, Q1, Q2, col, lw)
n = size(Q1,1);
X = [Q1(:,1)'; Q2(:,1)'; nan(1,n)]; X = X(:);
Y = [Q1(:,2)'; Q2(:,2)'; nan(1,n)]; Y = Y(:);
sh = [-2*pi 0 2*pi];
for dx = sh
    for dy = sh
        plot(ax, X+dx, Y+dy, '-', 'Color', col, 'LineWidth', lw, 'Clipping','on');
    end
end
end

function drawToroidSegs3(ax,A,B,col,lw,lineStyle)
if nargin < 6, lineStyle = '-'; end
B = A + wrapPi(B-A);
n = size(A,1);
for sx = [-2*pi 0 2*pi]
    for sy = [-2*pi 0 2*pi]
        for sz = [-2*pi 0 2*pi]
            shift = [sx sy sz]; As = A+shift; Bs = B+shift;
            X = [As(:,1)';Bs(:,1)';nan(1,n)];
            Y = [As(:,2)';Bs(:,2)';nan(1,n)];
            Z = [As(:,3)';Bs(:,3)';nan(1,n)];
            plot3(ax,X(:),Y(:),Z(:),lineStyle,'Color',col, ...
                'LineWidth',lw,'Clipping','on');
        end
    end
end
end

function drawPeriodicYSegs3(ax,A,B,col,lw,lineStyle)

if nargin < 6, lineStyle = '-'; end
B(:,2) = A(:,2) + wrapPi(B(:,2)-A(:,2));
n = size(A,1);
for sy = [-2*pi 0 2*pi]
    As = A; Bs = B;
    As(:,2) = As(:,2) + sy;
    Bs(:,2) = Bs(:,2) + sy;
    X = [As(:,1)';Bs(:,1)';nan(1,n)];
    Y = [As(:,2)';Bs(:,2)';nan(1,n)];
    Z = [As(:,3)';Bs(:,3)';nan(1,n)];
    plot3(ax,X(:),Y(:),Z(:),lineStyle,'Color',col, ...
        'LineWidth',lw,'Clipping','on');
end
end

function [U,info] = prmSample(count,dim,mode,noiseDir,haltonStart)

persistent pool cursor srcName
if isempty(pool), pool = uint8([]); cursor = 1; srcName = ''; end

switch lower(mode)
    case 'halton'
        shift = rand(1,dim);
        U = mod(haltonND(haltonStart,count,dim) + shift, 1);
        info = 'randomized Halton';
        return
    case 'halton_fixed'
        U = haltonND(haltonStart,count,dim);
        info = 'fixed Halton (repeatable)';
        return
    case 'rand'
        U = rand(count,dim);
        info = 'rand (Mersenne Twister)';
        return
end

need = count*dim*3;
guard = 0;
while numel(pool) - cursor + 1 < need
    guard = guard + 1;
    if guard > 4
        U = rand(count,dim);
        info = 'fallback: rand (entropy pool could not refill)';
        return
    end
    [bytes,src] = fetchEntropy(mode,noiseDir,max(need,131072));
    if isempty(bytes)
        U = rand(count,dim);
        info = 'fallback: rand (entropy source failed)';
        return
    end
    pool = [pool(cursor:end); bytes];
    cursor = 1;
    srcName = src;
end

b = double(pool(cursor:cursor+need-1));
cursor = cursor + need;
b = reshape(b,3,[])';
u = (b(:,1)*65536 + b(:,2)*256 + b(:,3)) / 16777216;
U = reshape(u,count,dim);
info = sprintf('%s, %d bytes left',srcName,numel(pool)-cursor+1);
end

function [bytes,src] = fetchEntropy(mode,noiseDir,minBytes)
bytes = uint8([]); src = '';
switch lower(mode)
    case 'image'
        files = noiseImageList(noiseDir);
        if isempty(files), return; end
        while numel(bytes) < minBytes
            k = randi(numel(files));
            b = bytesFromImage(files{k});
            if isempty(b)
                files(k) = [];
                if isempty(files), break; end
                continue
            end
            bytes = [bytes; b];
            src = sprintf('noise image %s',files{k});
            if numel(files) == 1, break; end
        end
    case 'api'
        bytes = bytesFromRandomOrg(minBytes);
        src = 'random.org (atmospheric noise)';
end
end

function files = noiseImageList(noiseDir)
files = {};
if isempty(noiseDir) || ~isfolder(noiseDir), return; end
ext = {'*.png','*.bmp','*.tif','*.tiff','*.jpg','*.jpeg'};
for k = 1:numel(ext)
    d = dir(fullfile(noiseDir,ext{k}));
    for j = 1:numel(d)
        files{end+1} = fullfile(d(j).folder,d(j).name);
    end
end
end

function bytes = bytesFromImage(file)
bytes = uint8([]);
try
    I = imread(file);
catch
    return
end
I = uint8(I(:));
bits = [bitand(I,1); bitand(bitshift(I,-1),1)];
bits = vonNeumannDebias(bits);
nb = floor(numel(bits)/8)*8;
if nb < 8, return; end
w = 2.^(7:-1:0)';
bytes = uint8(sum(reshape(double(bits(1:nb)),8,[]) .* w, 1))';
end

function out = vonNeumannDebias(bits)
m = floor(numel(bits)/2)*2;
if m < 2, out = []; return; end
a = bits(1:2:m); b = bits(2:2:m);
keep = a ~= b;
out = a(keep);
end

function bytes = bytesFromRandomOrg(minBytes)
bytes = uint8([]);
remaining = minBytes;
while remaining > 0
    nreq = min(remaining,10000);
    url = sprintf(['https://www.random.org/integers/?num=%d&min=0&max=255' ...
        '&col=1&base=10&format=plain&rnd=new'],nreq);
    try
        txt = webread(url,weboptions('Timeout',10,'ContentType','text'));
    catch
        return
    end
    v = sscanf(txt,'%d');
    if isempty(v), return; end
    bytes = [bytes; uint8(v)];
    remaining = remaining - numel(v);
end
end

function U = haltonND(firstIndex,count,dim)
base = [2 3 5 7 11 13 17 19];
U = zeros(count,dim);
idx = (firstIndex:firstIndex+count-1)';
for d = 1:dim
    bse = base(d); f = 1; r = zeros(count,1); i = idx;
    while any(i > 0)
        f = f/bse;
        r = r + f*mod(i,bse);
        i = floor(i/bse);
    end
    U(:,d) = r;
end
end

function pth = astarGeneric(A,V,si,gi,distFcn)

n = numel(A);
g = inf(n,1); fsc = inf(n,1); came = zeros(n,1);
closed = false(n,1); open = false(n,1);
g(si) = 0; fsc(si) = distFcn(V(si,:),V(gi,:)); open(si) = true;
pth = [];
while any(open)
    idxs = find(open);
    [~,k] = min(fsc(idxs));
    cur = idxs(k);
    if cur == gi
        pth = cur;
        while came(pth(1)) ~= 0
            pth = [came(pth(1)) pth];
        end
        return
    end
    open(cur) = false; closed(cur) = true;
    for nb = A{cur}
        if closed(nb), continue; end
        tentative = g(cur) + distFcn(V(cur,:),V(nb,:));
        if tentative < g(nb)
            came(nb) = cur;
            g(nb) = tentative;
            fsc(nb) = tentative + distFcn(V(nb,:),V(gi,:));
            open(nb) = true;
        end
    end
end
end

function lab = connectedComponents(adj)

nn = numel(adj); lab = zeros(nn,1); c = 0; st = zeros(nn,1);
for s0 = 1:nn
    if lab(s0), continue; end
    c = c + 1; sp = 1; st(1) = s0; lab(s0) = c;
    while sp > 0
        v = st(sp); sp = sp - 1;
        for u = adj{v}
            if ~lab(u), lab(u) = c; sp = sp + 1; st(sp) = u; end
        end
    end
end
end

function b = fbdB64Decode(s)

s   = s(s > 32);
lut = zeros(1,128);
lut(double(['A':'Z' 'a':'z' '0':'9' '+' '/'])) = 0:63;
v = uint32(lut(double(s)));
g = floor(numel(v)/4);
c = reshape(v(1:g*4),4,g);
w = bitshift(c(1,:),18) + bitshift(c(2,:),12) + bitshift(c(3,:),6) + c(4,:);
b = uint8(reshape([bitand(bitshift(w,-16),255); ...
                   bitand(bitshift(w, -8),255); ...
                   bitand(w,255)],1,[]));
end

function [V,F] = fbdMeshDecode(k)

b  = fbdB64Decode(fbdMeshBlob(k));
nV = double(typecast(b(1:4),'uint32'));
nF = double(typecast(b(5:8),'uint32'));
hd = double(typecast(b(9:32),'single'));
mn = hd(1:3); sz = hd(4:6);
o  = 32;
V  = double(typecast(b(o+1:o+nV*6),'uint16'));
V  = reshape(V,3,nV)'/65535;
V  = V.*repmat(sz,nV,1) + repmat(mn,nV,1);
o  = o + nV*6;
F  = double(typecast(b(o+1:o+nF*6),'uint16'));
F  = reshape(F,3,nF)' + 1;
end

